    public async Task<DeliveryDto> Ready(Guid tenantId,Guid orderId,ReadyDeliveryInput input,Guid actorId,string actor,CancellationToken token)
    {
        await using var c=await Open(token);await using var tx=(SqlTransaction)await c.BeginTransactionAsync(token);await using(var kind=new SqlCommand("SELECT OrderType FROM sales.SalesInvoices WITH(UPDLOCK,HOLDLOCK) WHERE TenantId=@tenant AND InvoiceId=@order;",c,tx)){P(kind,"@tenant",tenantId);P(kind,"@order",orderId);if(StringValue(await kind.ExecuteScalarAsync(token))=="MARKETPLACE")throw new BusinessRuleException("Marketplace orders must be operated through their fulfilment groups.");}Guid deliveryId;Guid? agent;string? source;string current;
        await using(var existing=new SqlCommand("SELECT OrderDeliveryId,DeliveryAgentId,AssignmentSource,DeliveryStatus FROM commerce.OrderDeliveries WITH(UPDLOCK,HOLDLOCK) WHERE TenantId=@tenant AND OrderId=@order",c,tx)){P(existing,"@tenant",tenantId);P(existing,"@order",orderId);await using var r=await existing.ExecuteReaderAsync(token);if(await r.ReadAsync(token)){deliveryId=r.GetGuid(0);agent=r.IsDBNull(1)?null:r.GetGuid(1);source=S(r,2);current=r.GetString(3);}else{deliveryId=Guid.Empty;agent=null;source=null;current=DeliveryStatuses.Unassigned;}}
        if(deliveryId!=Guid.Empty&&source=="MANUAL"&&input.DeliveryAgentId is null){await tx.CommitAsync(token);return await Get(tenantId,deliveryId,null,true,token);}
        await EnsurePrepaidSettled(c,tx,tenantId,orderId,token);
        var previousAgent=agent;var previousSource=source;(agent,source)=await ResolveAssignment(c,tx,tenantId,input.DeliveryAgentId,token);var status=agent is null?DeliveryStatuses.Unassigned:DeliveryStatuses.Ready;
        if(deliveryId!=Guid.Empty&&previousAgent==agent&&string.Equals(previousSource,source,StringComparison.OrdinalIgnoreCase)&&current==status){await tx.CommitAsync(token);return await Get(tenantId,deliveryId,null,true,token);}
        if(deliveryId==Guid.Empty){deliveryId=Guid.NewGuid();await using var q=new SqlCommand(@"INSERT commerce.OrderDeliveries(OrderDeliveryId,TenantId,OrderId,DeliveryAgentId,DeliveryStatus,AssignmentSource,AssignedAt,AssignedBy,ReadyAt,CustomerNameSnapshot,CustomerMobileSnapshot,DeliveryAddressSnapshot,DeliveryNotes,CodRequired,CodAmount,SourceChannel) SELECT @id,@tenant,i.InvoiceId,@agent,@status,@source,CASE WHEN @agent IS NULL THEN NULL ELSE SYSUTCDATETIME() END,CASE WHEN @agent IS NULL THEN NULL ELSE @actor END,SYSUTCDATETIME(),cu.CustomerName,cu.Mobile,COALESCE(NULLIF(@address,''),NULLIF(w.DeliveryAddress,''),CONCAT_WS(', ',a.AddressLine1,a.AddressLine2,a.City,a.State,a.PostalCode),N'Address not provided'),@notes,COALESCE(@cod,CASE WHEN w.PaymentType='COD' THEN 1 ELSE 0 END),CASE WHEN COALESCE(@cod,CASE WHEN w.PaymentType='COD' THEN 1 ELSE 0 END)=1 THEN i.BalanceAmount ELSE 0 END,CASE WHEN w.InvoiceId IS NULL THEN N'ERP' ELSE w.SourceChannel END FROM sales.SalesInvoices i JOIN sales.Customers cu ON cu.CustomerId=i.CustomerId AND cu.TenantId=i.TenantId LEFT JOIN integration.WhatsAppCommerceOrders w ON w.InvoiceId=i.InvoiceId AND w.TenantId=i.TenantId OUTER APPLY(SELECT TOP(1) ca.AddressLine1,ca.AddressLine2,ca.City,ca.State,ca.PostalCode FROM sales.CustomerAddresses ca WHERE ca.CustomerId=cu.CustomerId AND ca.AddressType='Shipping') a WHERE i.InvoiceId=@order AND i.TenantId=@tenant AND i.OrderType='STANDARD' AND i.Status NOT IN('CANCELLED','VOID','RETURNED')",c,tx);P(q,"@id",deliveryId);P(q,"@tenant",tenantId);P(q,"@order",orderId);P(q,"@agent",agent);P(q,"@status",status);P(q,"@source",source);P(q,"@actor",actorId);P(q,"@address",input.DeliveryAddress);P(q,"@notes",input.DeliveryNotes);P(q,"@cod",input.CodRequired);if(await q.ExecuteNonQueryAsync(token)!=1)throw new EntityNotFoundException("The active order was not found for this tenant or has no customer.");await Event(c,tx,tenantId,deliveryId,"CREATED",null,status,null,agent,actorId,"Order became ready for delivery",token);}
        else {await using var q=new SqlCommand("UPDATE commerce.OrderDeliveries SET DeliveryAgentId=@agent,DeliveryStatus=@status,AssignmentSource=@source,AssignedAt=CASE WHEN @agent IS NULL THEN NULL ELSE SYSUTCDATETIME() END,AssignedBy=CASE WHEN @agent IS NULL THEN NULL ELSE @actor END,ReadyAt=COALESCE(ReadyAt,SYSUTCDATETIME()),UpdatedAt=SYSUTCDATETIME() WHERE TenantId=@tenant AND OrderDeliveryId=@id AND DeliveryStatus NOT IN('DELIVERED','CANCELLED','RETURNED')",c,tx);P(q,"@agent",agent);P(q,"@status",status);P(q,"@source",source);P(q,"@actor",actorId);P(q,"@tenant",tenantId);P(q,"@id",deliveryId);if(await q.ExecuteNonQueryAsync(token)==0)throw new BusinessRuleException("A completed delivery cannot be made ready again.");await Event(c,tx,tenantId,deliveryId,"READY",current,status,null,agent,actorId,null,token);}
        await tx.CommitAsync(token);if(agent is not null&&(await Settings(tenantId,token)).NotifyOnAssigned)await Notify(tenantId,deliveryId,DeliveryTemplateKeys.Assigned,null,token);return await Get(tenantId,deliveryId,null,true,token);
    }

    public async Task<IReadOnlyCollection<MarketplaceFulfilmentGroupDto>> MarketplaceGroups(Guid tenantId,Guid orderId,Guid userId,bool manage,CancellationToken token)
    {
        tenantId=AuthenticatedTenant(tenantId);
        await using var c=await Open(token);
        await using(var context=new SqlCommand("EXEC sys.sp_set_session_context @key=N'TenantId',@value=@tenant;",c)){P(context,"@tenant",tenantId);await context.ExecuteNonQueryAsync(token);}
        await EnsureMarketplaceParent(c,null,tenantId,orderId,token);
        var ids=new List<Guid>();
        await using(var q=new SqlCommand("SELECT g.FulfilmentGroupId FROM commerce.MarketplaceFulfilmentGroups g LEFT JOIN commerce.DeliveryAgents a ON a.TenantId=g.TenantId AND a.DeliveryAgentId=g.DeliveryAgentId WHERE g.TenantId=@tenant AND g.OrderId=@order AND (@manage=1 OR a.UserId=@user) ORDER BY g.GroupNumber;",c))
        {P(q,"@tenant",tenantId);P(q,"@order",orderId);P(q,"@manage",manage);P(q,"@user",userId);await using var r=await q.ExecuteReaderAsync(token);while(await r.ReadAsync(token))ids.Add(r.GetGuid(0));}
        var result=new List<MarketplaceFulfilmentGroupDto>(ids.Count);
        foreach(var id in ids)result.Add(await ReadMarketplaceGroup(c,tenantId,orderId,id,token));
        return result;
    }

    public async Task<IReadOnlyCollection<MarketplaceDeliveryOrderDto>> MarketplaceDeliveryOrders(Guid tenantId,Guid userId,bool manage,CancellationToken token)
    {
        tenantId=AuthenticatedTenant(tenantId);
        await using var c=await Open(token);
        await using(var context=new SqlCommand("EXEC sys.sp_set_session_context @key=N'TenantId',@value=@tenant;",c)){P(context,"@tenant",tenantId);await context.ExecuteNonQueryAsync(token);}
        var result=new List<MarketplaceDeliveryOrderDto>();
        await using var q=new SqlCommand(@"SELECT i.InvoiceId,i.InvoiceNumber,i.InvoiceDate,COALESCE(c.CustomerName,N'Customer'),i.GrandTotal,
COALESCE(cp.PaymentMethod,w.PaymentType,N'UNKNOWN'),COALESCE(cp.Status,N'PENDING'),COUNT(DISTINCT g.FulfilmentGroupId)
FROM commerce.MarketplaceOrders o
JOIN sales.SalesInvoices i ON i.TenantId=o.TenantId AND i.InvoiceId=o.OrderId AND i.OrderType='MARKETPLACE'
JOIN sales.Customers c ON c.TenantId=i.TenantId AND c.CustomerId=i.CustomerId
JOIN commerce.MarketplaceFulfilmentGroups g ON g.TenantId=o.TenantId AND g.OrderId=o.OrderId
LEFT JOIN commerce.DeliveryAgents a ON a.TenantId=g.TenantId AND a.DeliveryAgentId=g.DeliveryAgentId
LEFT JOIN integration.WhatsAppCommerceOrders w ON w.TenantId=i.TenantId AND w.InvoiceId=i.InvoiceId AND w.SourceChannel=N'STOREFRONT'
OUTER APPLY(SELECT TOP(1) p.PaymentMethod,p.Status FROM commerce.CommercePayments p WHERE p.TenantId=i.TenantId AND p.InvoiceId=i.InvoiceId ORDER BY CASE WHEN p.Status IN(N'PAID',N'CAPTURED') THEN 0 ELSE 1 END,p.AttemptNumber DESC,p.CreatedAt DESC) cp
WHERE o.TenantId=@tenant AND (@manage=1 OR a.UserId=@user)
GROUP BY i.InvoiceId,i.InvoiceNumber,i.InvoiceDate,c.CustomerName,i.GrandTotal,cp.PaymentMethod,w.PaymentType,cp.Status
ORDER BY i.InvoiceDate DESC,i.InvoiceNumber;",c);
        P(q,"@tenant",tenantId);P(q,"@user",userId);P(q,"@manage",manage);
        await using var r=await q.ExecuteReaderAsync(token);
        while(await r.ReadAsync(token))
        {
            var method=r.GetString(5);var payment=r.GetString(6);
            result.Add(new(r.GetGuid(0),r.GetString(1),r.GetDateTimeOffset(2),r.GetString(3),r.GetDecimal(4),method,StorefrontOrderPresentation.PaymentStatus(payment,method),r.GetInt32(7)));
        }
        return result;
    }

    public async Task<MarketplaceFulfilmentGroupDto> AssignMarketplaceGroup(Guid tenantId,Guid orderId,Guid groupId,MarketplaceGroupAssignmentInput input,Guid userId,string actor,bool manage,bool canAssign,CancellationToken token)
    {
        tenantId=AuthenticatedTenant(tenantId);if(!manage&&!canAssign)throw new WhatsBiz.Application.Common.Exceptions.UnauthorizedAccessException("Delivery assignment permission is required to assign a fulfilment group.");
        await using var c=await Open(token);await using var tx=(SqlTransaction)await c.BeginTransactionAsync(token);await SetTenantContext(c,tx,tenantId,token);
        await EnsureMarketplaceParent(c,tx,tenantId,orderId,token);
        var old=await ReadMarketplaceGroupState(c,tx,tenantId,orderId,groupId,token);
        if(old.Status is "DELIVERED" or "CANCELLED")throw new BusinessRuleException("A completed fulfilment group cannot be reassigned.");
        var (agent,source)=await ResolveMarketplaceAssignment(c,tx,tenantId,input.DeliveryAgentId,token);
        if(agent==old.Agent&&string.Equals(source,old.Source,StringComparison.OrdinalIgnoreCase)){await tx.CommitAsync(token);return await ReadMarketplaceGroup(c,tenantId,orderId,groupId,token);}
        await using(var update=new SqlCommand("UPDATE commerce.MarketplaceFulfilmentGroups SET DeliveryAgentId=@agent,AssignmentSource=@source,UpdatedAt=SYSUTCDATETIME() WHERE TenantId=@tenant AND OrderId=@order AND FulfilmentGroupId=@group;",c,tx))
        {P(update,"@agent",agent);P(update,"@source",source);P(update,"@tenant",tenantId);P(update,"@order",orderId);P(update,"@group",groupId);if(await update.ExecuteNonQueryAsync(token)!=1)throw new EntityNotFoundException("Fulfilment group was not found.");}
        await MarketplaceGroupEvent(c,tx,tenantId,groupId,old.Status,old.Status,agent==null?"AGENT_UNASSIGNED":old.Agent==null?"AGENT_ASSIGNED":"AGENT_REASSIGNED",agent,userId,input.Reason,token);
        await tx.CommitAsync(token);return await ReadMarketplaceGroup(c,tenantId,orderId,groupId,token);
    }

    public async Task RequestMarketplaceGroupOtp(Guid tenantId,Guid orderId,Guid groupId,Guid userId,string actor,bool manage,CancellationToken token)
    {
        tenantId=AuthenticatedTenant(tenantId);var settings=await Settings(tenantId,token);
        if(!settings.RequireDeliveryOtp)throw new BusinessRuleException("Delivery OTP is disabled for this tenant.");
        await using var c=await Open(token);await using var tx=(SqlTransaction)await c.BeginTransactionAsync(token);await SetTenantContext(c,tx,tenantId,token);
        await EnsureMarketplaceParent(c,tx,tenantId,orderId,token);var group=await ReadMarketplaceGroupState(c,tx,tenantId,orderId,groupId,token);
        if(group.Status!="OUT_FOR_DELIVERY")throw new BusinessRuleException("A delivery OTP can be requested only for a group that is out for delivery.");
        if(!manage&&group.AgentUserId!=userId)throw new EntityNotFoundException("Fulfilment group was not found for this delivery agent.");
        await ValidateAssignedGroupAgent(c,tx,tenantId,groupId,group.Agent,token);
        var now=DateTimeOffset.UtcNow;var resend=0;
        await using(var old=new SqlCommand("SELECT ResendCount,LastSentAt,VerifiedAt FROM commerce.MarketplaceFulfilmentGroupOtps WITH(UPDLOCK,HOLDLOCK) WHERE TenantId=@tenant AND OrderId=@order AND FulfilmentGroupId=@group;",c,tx))
        {P(old,"@tenant",tenantId);P(old,"@order",orderId);P(old,"@group",groupId);await using var r=await old.ExecuteReaderAsync(token);if(await r.ReadAsync(token)){if(!r.IsDBNull(2))throw new BusinessRuleException("This fulfilment group has already been confirmed.");resend=r.GetInt32(0)+1;if(resend>settings.MaxOtpResends)throw new BusinessRuleException("Maximum OTP resend count has been reached.");if(now-r.GetDateTimeOffset(1)<TimeSpan.FromSeconds(settings.OtpResendCooldownSeconds))throw new BusinessRuleException("Please wait before requesting another delivery OTP.");}}
        string otp;byte[] fingerprint;int collision;
        do
        {
            otp=RandomNumberGenerator.GetInt32(1000,10000).ToString(CultureInfo.InvariantCulture);fingerprint=MarketplaceOtpFingerprint(tenantId,orderId,otp);
            await using var collisionCheck=new SqlCommand("SELECT COUNT(*) FROM commerce.MarketplaceFulfilmentGroupOtps WITH(UPDLOCK,HOLDLOCK) WHERE TenantId=@tenant AND OrderId=@order AND FulfilmentGroupId<>@group AND OtpFingerprint=@fingerprint;",c,tx);P(collisionCheck,"@tenant",tenantId);P(collisionCheck,"@order",orderId);P(collisionCheck,"@group",groupId);P(collisionCheck,"@fingerprint",fingerprint);collision=Convert.ToInt32(await collisionCheck.ExecuteScalarAsync(token),CultureInfo.InvariantCulture);
        }while(collision>0);
        var salt=RandomNumberGenerator.GetBytes(32);var hash=MarketplaceOtpHash(tenantId,orderId,groupId,otp,salt);
        await using(var save=new SqlCommand(@"MERGE commerce.MarketplaceFulfilmentGroupOtps WITH(HOLDLOCK) AS target
USING(SELECT @tenant TenantId,@group FulfilmentGroupId) source ON target.TenantId=source.TenantId AND target.FulfilmentGroupId=source.FulfilmentGroupId
WHEN MATCHED THEN UPDATE SET OrderId=@order,OtpHash=@hash,OtpFingerprint=@fingerprint,OtpSalt=@salt,ExpiresAt=@expires,AttemptCount=0,ResendCount=@resend,LastSentAt=@now,VerifiedAt=NULL,InvalidatedAt=NULL,NotificationStatus='PENDING',NotificationReference=NULL,NotificationError=NULL,UpdatedAt=@now
WHEN NOT MATCHED THEN INSERT(TenantId,FulfilmentGroupId,OrderId,OtpHash,OtpFingerprint,OtpSalt,ExpiresAt,ResendCount,LastSentAt) VALUES(@tenant,@group,@order,@hash,@fingerprint,@salt,@expires,@resend,@now);",c,tx))
        {P(save,"@tenant",tenantId);P(save,"@group",groupId);P(save,"@order",orderId);P(save,"@hash",hash);P(save,"@fingerprint",fingerprint);P(save,"@salt",salt);P(save,"@expires",now.AddMinutes(settings.DeliveryOtpExpiryMinutes));P(save,"@resend",resend);P(save,"@now",now);await save.ExecuteNonQueryAsync(token);}
        await MarketplaceGroupEvent(c,tx,tenantId,groupId,group.Status,group.Status,"GROUP_OTP_REQUESTED",group.Agent,userId,$"Delivery OTP requested for group {groupId:N}.",token);
        await tx.CommitAsync(token);await NotifyMarketplaceGroupOtp(tenantId,orderId,groupId,otp,settings.DeliveryOtpExpiryMinutes,token);
    }

    public async Task<MarketplaceGroupCancellationResult> CancelMarketplaceGroup(Guid tenantId,Guid orderId,Guid groupId,MarketplaceGroupCancellationInput input,Guid userId,string actor,bool manage,CancellationToken token)
    {
        tenantId=AuthenticatedTenant(tenantId);if(!manage)throw new WhatsBiz.Application.Common.Exceptions.UnauthorizedAccessException("Delivery management permission is required to cancel a fulfilment group.");
        if(string.IsNullOrWhiteSpace(input.Reason)||input.Reason.Trim().Length>500)throw new BusinessRuleException("A cancellation reason is required and cannot exceed 500 characters.");
        await using var c=await Open(token);await using var tx=(SqlTransaction)await c.BeginTransactionAsync(token);await SetTenantContext(c,tx,tenantId,token);
        var lifecycle=await EnsureMarketplaceParent(c,tx,tenantId,orderId,token);
        await using(var parentCodLock=new SqlCommand("SELECT CollectionStatus FROM commerce.MarketplaceCodCollections WITH(UPDLOCK,HOLDLOCK) WHERE TenantId=@tenant AND OrderId=@order;",c,tx)){P(parentCodLock,"@tenant",tenantId);P(parentCodLock,"@order",orderId);await parentCodLock.ExecuteScalarAsync(token);}
        var group=await ReadMarketplaceGroupState(c,tx,tenantId,orderId,groupId,token);
        if(group.Status=="CANCELLED"){await tx.CommitAsync(token);return await MarketplaceCancellationResult(c,null,tenantId,orderId,groupId,token);}
        if(group.Status is "DELIVERED" or "OUT_FOR_DELIVERY")throw new BusinessRuleException("A delivered or out-for-delivery group cannot be cancelled. Complete the supported return workflow first.");
        if(!MarketplaceFulfilmentPolicy.CanTransition(group.Status,"CANCELLED"))throw new BusinessRuleException($"A group in {group.Status} cannot be cancelled.");

        int allocationCount,activeCount,consumedCount,invalidCount;
        await using(var q=new SqlCommand(@"SELECT COUNT(*),SUM(CASE WHEN r.ReservationStatus IN('RESERVED','CONFIRMED') THEN 1 ELSE 0 END),SUM(CASE WHEN r.ReservationStatus='CONSUMED' THEN 1 ELSE 0 END),SUM(CASE WHEN r.ReservationId IS NULL OR r.ReservationStatus NOT IN('RESERVED','CONFIRMED','CONSUMED') THEN 1 ELSE 0 END)
FROM commerce.MarketplaceFulfilmentGroupItems gi WITH(UPDLOCK,HOLDLOCK)
JOIN commerce.MarketplaceOrderAllocations a WITH(UPDLOCK,HOLDLOCK) ON a.TenantId=gi.TenantId AND a.AllocationId=gi.AllocationId
LEFT JOIN commerce.MarketplaceAllocationReservations r WITH(UPDLOCK,HOLDLOCK) ON r.TenantId=a.TenantId AND r.OrderId=a.OrderId AND r.AllocationId=a.AllocationId
WHERE gi.TenantId=@tenant AND gi.FulfilmentGroupId=@group;",c,tx))
        {P(q,"@tenant",tenantId);P(q,"@group",groupId);await using var r=await q.ExecuteReaderAsync(token);if(!await r.ReadAsync(token))throw new BusinessRuleException("The fulfilment group has no allocated items.");allocationCount=r.GetInt32(0);activeCount=r.IsDBNull(1)?0:r.GetInt32(1);consumedCount=r.IsDBNull(2)?0:r.GetInt32(2);invalidCount=r.IsDBNull(3)?0:r.GetInt32(3);}
        if(allocationCount==0||invalidCount>0||activeCount+consumedCount!=allocationCount)throw new BusinessRuleException("The group's inventory reservation state is inconsistent; cancellation requires authorized reconciliation.");
        Guid? restockTransaction=null;var releasedUnconsumed=false;
        if(activeCount>0)
        {
            int groupCount;await using(var count=new SqlCommand("SELECT COUNT(*) FROM commerce.MarketplaceFulfilmentGroups WITH(UPDLOCK,HOLDLOCK) WHERE TenantId=@tenant AND OrderId=@order;",c,tx)){P(count,"@tenant",tenantId);P(count,"@order",orderId);groupCount=Convert.ToInt32(await count.ExecuteScalarAsync(token),CultureInfo.InvariantCulture);}
            if(lifecycle!="CONFIRMED"||groupCount!=1||consumedCount!=0)throw new BusinessRuleException("Active reservations can be released only by cancelling the single-group, unposted parent order. Partial pre-post group cancellation requires allocation-aware invoice amendment.");
            await using var release=new SqlCommand("EXEC commerce.Marketplace_ReleaseOrder @TenantId=@tenant,@OrderId=@order,@ReleaseReason='CANCEL',@ModifiedBy=@actor;",c,tx);P(release,"@tenant",tenantId);P(release,"@order",orderId);P(release,"@actor",actor);await release.ExecuteNonQueryAsync(token);releasedUnconsumed=true;
        }
        else
        {
            if(lifecycle is not("POSTED" or "PARTIALLY_FULFILLED"))throw new BusinessRuleException("The parent inventory lifecycle does not permit group cancellation.");
            if(input.RestockTransactionId is null)throw new BusinessRuleException("Post and provide an approved stock increase/return transaction for the group's complete allocated quantities before cancelling.");
            restockTransaction=input.RestockTransactionId;await ValidateMarketplaceGroupRestock(c,tx,tenantId,groupId,restockTransaction.Value,token);
        }

        var refund=releasedUnconsumed?new MarketplaceRefundCalculation("NO_REFUND_REQUIRED",0m,null,false):await CalculateMarketplaceGroupRefund(c,tx,tenantId,orderId,groupId,token);
        Guid? codOwner=null;string? codStatus=null;
        await using(var codRead=new SqlCommand("SELECT CollectionStatus,CollectionFulfilmentGroupId FROM commerce.MarketplaceCodCollections WITH(UPDLOCK,HOLDLOCK) WHERE TenantId=@tenant AND OrderId=@order;",c,tx))
        {P(codRead,"@tenant",tenantId);P(codRead,"@order",orderId);await using var r=await codRead.ExecuteReaderAsync(token);if(await r.ReadAsync(token)){codStatus=r.GetString(0);codOwner=G(r,1);}}
        if(codStatus=="PENDING"&&codOwner==groupId)
        {
            Guid? nextOwner=null;await using(var find=new SqlCommand("SELECT TOP(1) FulfilmentGroupId FROM commerce.MarketplaceFulfilmentGroups WITH(UPDLOCK,HOLDLOCK) WHERE TenantId=@tenant AND OrderId=@order AND FulfilmentGroupId<>@group AND FulfilmentStatus NOT IN('CANCELLED','DELIVERED') ORDER BY GroupNumber;",c,tx))
            {P(find,"@tenant",tenantId);P(find,"@order",orderId);P(find,"@group",groupId);var value=await find.ExecuteScalarAsync(token);if(value is Guid id)nextOwner=id;}
            if(nextOwner is null)
            {
                if(!releasedUnconsumed)throw new BusinessRuleException("COD collection responsibility cannot be cancelled without an active fulfilment group to receive it.");
                await using var voidCollection=new SqlCommand("UPDATE commerce.MarketplaceCodCollections SET CollectionStatus='VOID',UpdatedAt=SYSUTCDATETIME() WHERE TenantId=@tenant AND OrderId=@order AND CollectionStatus='PENDING' AND CollectionFulfilmentGroupId=@group;",c,tx);P(voidCollection,"@tenant",tenantId);P(voidCollection,"@order",orderId);P(voidCollection,"@group",groupId);await voidCollection.ExecuteNonQueryAsync(token);
            }
            else
            {
                await using(var reassign=new SqlCommand("UPDATE commerce.MarketplaceCodCollections SET CollectionFulfilmentGroupId=@next,UpdatedAt=SYSUTCDATETIME() WHERE TenantId=@tenant AND OrderId=@order AND CollectionStatus='PENDING' AND CollectionFulfilmentGroupId=@old;",c,tx))
                {P(reassign,"@next",nextOwner);P(reassign,"@tenant",tenantId);P(reassign,"@order",orderId);P(reassign,"@old",groupId);if(await reassign.ExecuteNonQueryAsync(token)!=1)throw new BusinessRuleException("COD collection responsibility changed; refresh and retry.");}
                await MarketplaceGroupEvent(c,tx,tenantId,nextOwner.Value,group.Status,group.Status,"COD_COLLECTION_REASSIGNED",null,userId,"Parent COD collection responsibility reassigned after group cancellation.",token);
            }
        }
        await InsertMarketplaceGroupRefundObligation(c,tx,tenantId,orderId,groupId,restockTransaction,refund.Status,refund.Amount,refund.Reason,actor,token);
        await using(var settlementAdjustments=new SqlCommand("commerce.PartnerSettlement_CreateCancellationReviews",c,tx){CommandType=CommandType.StoredProcedure})
        {P(settlementAdjustments,"@TenantId",tenantId);P(settlementAdjustments,"@OrderId",orderId);P(settlementAdjustments,"@FulfilmentGroupId",groupId);P(settlementAdjustments,"@Actor",actor);P(settlementAdjustments,"@Reason",input.Reason.Trim());await settlementAdjustments.ExecuteNonQueryAsync(token);}
        if(refund.PaymentCollected)
        {
            await using var cod=new SqlCommand("UPDATE commerce.MarketplaceCodCollections SET CollectionStatus='REFUND_DUE',UpdatedAt=SYSUTCDATETIME() WHERE TenantId=@tenant AND OrderId=@order AND CollectionStatus='COLLECTED';",c,tx);P(cod,"@tenant",tenantId);P(cod,"@order",orderId);await cod.ExecuteNonQueryAsync(token);
        }
        await using(var update=new SqlCommand("UPDATE commerce.MarketplaceFulfilmentGroups SET FulfilmentStatus='CANCELLED',CancelledAt=SYSUTCDATETIME(),UpdatedAt=SYSUTCDATETIME() WHERE TenantId=@tenant AND OrderId=@order AND FulfilmentGroupId=@group AND FulfilmentStatus=@prior;",c,tx))
        {P(update,"@tenant",tenantId);P(update,"@order",orderId);P(update,"@group",groupId);P(update,"@prior",group.Status);if(await update.ExecuteNonQueryAsync(token)!=1)throw new BusinessRuleException("The fulfilment group changed during cancellation; refresh and retry.");}
        await MarketplaceGroupEvent(c,tx,tenantId,groupId,group.Status,"CANCELLED","GROUP_CANCELLED",group.Agent,userId,$"{input.Reason.Trim()} | Stock {(releasedUnconsumed?"reservation released":$"restock confirmed: {restockTransaction}")} | Refund {refund.Status}{(refund.Amount is null?string.Empty:$" {refund.Amount.Value:0.00}")}",token);
        if(refund.Status=="REVIEW_REQUIRED")await MarketplaceGroupEvent(c,tx,tenantId,groupId,group.Status,"CANCELLED","REFUND_REVIEW_REQUIRED",group.Agent,userId,refund.Reason,token);
        await tx.CommitAsync(token);return new(await ReadMarketplaceGroup(c,tenantId,orderId,groupId,token),refund.Status,refund.Amount,refund.Reason);
    }

    public async Task<MarketplaceFulfilmentGroupDto> TransitionMarketplaceGroup(Guid tenantId,Guid orderId,Guid groupId,MarketplaceGroupTransitionInput input,Guid userId,string actor,bool manage,bool canConfirm,bool overrideOtp,CancellationToken token)
    {
        tenantId=AuthenticatedTenant(tenantId);var target=input.Status?.Trim().ToUpperInvariant()??string.Empty;
        if(target=="CANCELLED")throw new BusinessRuleException("Marketplace group cancellation requires allocation-aware inventory return and refund reconciliation, which is not available yet.");
        if(target is not("PREPARING" or "READY_FOR_DISPATCH" or "OUT_FOR_DELIVERY" or "DELIVERED" or "DELIVERY_FAILED"))throw new BusinessRuleException("Select a valid fulfilment status.");
        if(input.TrackingReference?.Trim().Length>160)throw new BusinessRuleException("Tracking reference cannot exceed 160 characters.");
        if(target=="DELIVERY_FAILED"&&string.IsNullOrWhiteSpace(input.Reason))throw new BusinessRuleException("A reason is required for failed delivery.");
        if(target=="DELIVERED"&&!canConfirm)throw new WhatsBiz.Application.Common.Exceptions.UnauthorizedAccessException("Delivery confirmation permission is required.");
        await using var c=await Open(token);await using var tx=(SqlTransaction)await c.BeginTransactionAsync(token);await SetTenantContext(c,tx,tenantId,token);
        var lifecycle=await EnsureMarketplaceParent(c,tx,tenantId,orderId,token);
        var row=await ReadMarketplaceGroupState(c,tx,tenantId,orderId,groupId,token);
        if(!manage&&row.AgentUserId!=userId)throw new EntityNotFoundException("Fulfilment group was not found for this delivery agent.");
        if(row.Status==target){await tx.CommitAsync(token);return await ReadMarketplaceGroup(c,tenantId,orderId,groupId,token);}
        var allowed=MarketplaceFulfilmentPolicy.CanTransition(row.Status,target)
            &&(target is not("OUT_FOR_DELIVERY" or "DELIVERED")||row.Agent is not null);
        if(!allowed)throw new BusinessRuleException($"Fulfilment group cannot transition from {row.Status} to {target}.");
        if(target=="OUT_FOR_DELIVERY"&&lifecycle is not("POSTED" or "PARTIALLY_FULFILLED"))throw new BusinessRuleException("Marketplace inventory must be posted before dispatch.");
        if(target is "OUT_FOR_DELIVERY" or "DELIVERED")await ValidateAssignedGroupAgent(c,tx,tenantId,groupId,row.Agent,token);
        if(target=="DELIVERED")
        {
            if(lifecycle is not("POSTED" or "PARTIALLY_FULFILLED"))throw new BusinessRuleException("Marketplace inventory must be posted before delivery can be confirmed.");
            await using var otpSetting=new SqlCommand("SELECT RequireDeliveryOtp,MaxOtpAttempts FROM commerce.TenantDeliverySettings WHERE TenantId=@tenant;",c,tx);P(otpSetting,"@tenant",tenantId);bool requireOtp;int maxOtpAttempts;await using(var settingsRow=await otpSetting.ExecuteReaderAsync(token)){if(!await settingsRow.ReadAsync(token))throw new BusinessRuleException("Delivery settings are unavailable.");requireOtp=settingsRow.GetBoolean(0);maxOtpAttempts=settingsRow.GetInt32(1);}
            if(requireOtp&&!overrideOtp)
            {
                if(input.Otp?.Length!=4||!input.Otp.All(char.IsDigit))throw new BusinessRuleException("A valid four-digit delivery OTP is required for this fulfilment group.");
                byte[] hash,salt;DateTimeOffset expires;int attempts;DateTimeOffset? verified,invalidated;
                await using(var otp=new SqlCommand("SELECT OtpHash,OtpSalt,ExpiresAt,AttemptCount,VerifiedAt,InvalidatedAt FROM commerce.MarketplaceFulfilmentGroupOtps WITH(UPDLOCK,HOLDLOCK) WHERE TenantId=@tenant AND OrderId=@order AND FulfilmentGroupId=@group;",c,tx))
                {P(otp,"@tenant",tenantId);P(otp,"@order",orderId);P(otp,"@group",groupId);await using var r=await otp.ExecuteReaderAsync(token);if(!await r.ReadAsync(token))throw new BusinessRuleException("Request a delivery OTP for this group first.");hash=(byte[])r[0];salt=(byte[])r[1];expires=r.GetDateTimeOffset(2);attempts=r.GetInt32(3);verified=r.IsDBNull(4)?null:r.GetDateTimeOffset(4);invalidated=r.IsDBNull(5)?null:r.GetDateTimeOffset(5);}
                if(verified is not null)throw new BusinessRuleException("This fulfilment group has already used its delivery OTP.");
                if(invalidated is not null||expires<=DateTimeOffset.UtcNow)throw new BusinessRuleException("The delivery OTP has expired. Request a new OTP.");
                if(attempts>=maxOtpAttempts)throw new BusinessRuleException("Maximum delivery OTP attempts have been reached.");
                if(!CryptographicOperations.FixedTimeEquals(hash,MarketplaceOtpHash(tenantId,orderId,groupId,input.Otp,salt)))
                {await using var bad=new SqlCommand("UPDATE commerce.MarketplaceFulfilmentGroupOtps SET AttemptCount=AttemptCount+1,InvalidatedAt=CASE WHEN AttemptCount+1>=@max THEN SYSUTCDATETIME() END,UpdatedAt=SYSUTCDATETIME() WHERE TenantId=@tenant AND OrderId=@order AND FulfilmentGroupId=@group;",c,tx);P(bad,"@max",maxOtpAttempts);P(bad,"@tenant",tenantId);P(bad,"@order",orderId);P(bad,"@group",groupId);await bad.ExecuteNonQueryAsync(token);await tx.CommitAsync(token);throw new BusinessRuleException("The delivery OTP is incorrect.");}
                await using(var verifiedOtp=new SqlCommand("UPDATE commerce.MarketplaceFulfilmentGroupOtps SET VerifiedAt=SYSUTCDATETIME(),InvalidatedAt=SYSUTCDATETIME(),UpdatedAt=SYSUTCDATETIME() WHERE TenantId=@tenant AND OrderId=@order AND FulfilmentGroupId=@group AND VerifiedAt IS NULL AND InvalidatedAt IS NULL;",c,tx)){P(verifiedOtp,"@tenant",tenantId);P(verifiedOtp,"@order",orderId);P(verifiedOtp,"@group",groupId);if(await verifiedOtp.ExecuteNonQueryAsync(token)!=1)throw new BusinessRuleException("The delivery OTP changed; request a new code.");}
                await MarketplaceGroupEvent(c,tx,tenantId,groupId,row.Status,row.Status,"GROUP_OTP_VERIFIED",row.Agent,userId,"Delivery OTP verified for this fulfilment group.",token);
            }
            if(overrideOtp&&string.IsNullOrWhiteSpace(input.Reason))throw new BusinessRuleException("A reason is required when confirming a group delivery without OTP.");
            await using var cod=new SqlCommand("SELECT w.PaymentType,c.CollectionStatus FROM integration.WhatsAppCommerceOrders w WITH(UPDLOCK,HOLDLOCK) LEFT JOIN commerce.MarketplaceCodCollections c WITH(UPDLOCK,HOLDLOCK) ON c.TenantId=w.TenantId AND c.OrderId=w.InvoiceId WHERE w.TenantId=@tenant AND w.InvoiceId=@order;",c,tx);P(cod,"@tenant",tenantId);P(cod,"@order",orderId);
            await using(var codRow=await cod.ExecuteReaderAsync(token))
            {
                if(!await codRow.ReadAsync(token))throw new BusinessRuleException("Marketplace payment details are unavailable; delivery cannot be confirmed.");
                var paymentType=codRow.IsDBNull(0)?string.Empty:codRow.GetString(0);
                var collectionStatus=codRow.IsDBNull(1)?null:codRow.GetString(1);
                if(string.Equals(paymentType,"COD",StringComparison.OrdinalIgnoreCase)&&collectionStatus is not("COLLECTED" or "REFUND_DUE"))
                    throw new BusinessRuleException("The full parent-order COD amount must be collected before confirming any fulfilment delivery.");
            }
        }
        var updateSql="UPDATE commerce.MarketplaceFulfilmentGroups SET FulfilmentStatus=@target,TrackingReference=COALESCE(NULLIF(@tracking,N''),TrackingReference),ReadyAt=CASE WHEN @target='READY_FOR_DISPATCH' THEN COALESCE(ReadyAt,SYSUTCDATETIME()) ELSE ReadyAt END,DispatchedAt=CASE WHEN @target='OUT_FOR_DELIVERY' THEN COALESCE(DispatchedAt,SYSUTCDATETIME()) ELSE DispatchedAt END,DeliveredAt=CASE WHEN @target='DELIVERED' THEN SYSUTCDATETIME() ELSE DeliveredAt END,CancelledAt=CASE WHEN @target='CANCELLED' THEN SYSUTCDATETIME() ELSE CancelledAt END,UpdatedAt=SYSUTCDATETIME() WHERE TenantId=@tenant AND OrderId=@order AND FulfilmentGroupId=@group AND FulfilmentStatus=@prior;";
        await using(var update=new SqlCommand(updateSql,c,tx)){P(update,"@target",target);P(update,"@tracking",input.TrackingReference?.Trim());P(update,"@tenant",tenantId);P(update,"@order",orderId);P(update,"@group",groupId);P(update,"@prior",row.Status);if(await update.ExecuteNonQueryAsync(token)!=1)throw new BusinessRuleException("Fulfilment state changed; refresh and retry.");}
        await MarketplaceGroupEvent(c,tx,tenantId,groupId,row.Status,target,overrideOtp?"DELIVERED_OVERRIDE":$"GROUP_{target}",row.Agent,userId,input.Reason,token);
        if(target=="DELIVERY_FAILED")
        {
            await using var codState=new SqlCommand("UPDATE commerce.MarketplaceCodCollections SET CollectionStatus='REFUND_DUE',UpdatedAt=SYSUTCDATETIME() WHERE TenantId=@tenant AND OrderId=@order AND CollectionStatus='COLLECTED';SELECT @@ROWCOUNT;",c,tx);P(codState,"@tenant",tenantId);P(codState,"@order",orderId);
            if(Convert.ToInt32(await codState.ExecuteScalarAsync(token),CultureInfo.InvariantCulture)>0)await MarketplaceGroupEvent(c,tx,tenantId,groupId,row.Status,target,"COD_REFUND_REVIEW_REQUIRED",row.Agent,userId,"Parent COD was collected; refund or adjustment is due while this group remains undelivered.",token);
        }
        if(target=="DELIVERED"&&row.Status=="DELIVERY_FAILED")
        {
            await using var recoverCod=new SqlCommand("UPDATE commerce.MarketplaceCodCollections SET CollectionStatus='COLLECTED',UpdatedAt=SYSUTCDATETIME() WHERE TenantId=@tenant AND OrderId=@order AND CollectionStatus='REFUND_DUE' AND NOT EXISTS(SELECT 1 FROM commerce.MarketplaceFulfilmentGroups WHERE TenantId=@tenant AND OrderId=@order AND FulfilmentStatus='DELIVERY_FAILED');SELECT @@ROWCOUNT;",c,tx);P(recoverCod,"@tenant",tenantId);P(recoverCod,"@order",orderId);
            if(Convert.ToInt32(await recoverCod.ExecuteScalarAsync(token),CultureInfo.InvariantCulture)>0)await MarketplaceGroupEvent(c,tx,tenantId,groupId,row.Status,target,"COD_REFUND_REVIEW_RECOVERED",row.Agent,userId,"The failed group was delivered after retry; the parent refund or adjustment obligation was cleared.",token);
        }
        if(target=="DELIVERED")await ReconcileMarketplaceParent(c,tx,tenantId,orderId,token);
        await tx.CommitAsync(token);return await ReadMarketplaceGroup(c,tenantId,orderId,groupId,token);
    }

    private static async Task<string> EnsureMarketplaceParent(SqlConnection c,SqlTransaction? tx,Guid tenant,Guid order,CancellationToken token)
    {
        await using var q=new SqlCommand("SELECT o.LifecycleStatus FROM commerce.MarketplaceOrders o WITH(UPDLOCK,HOLDLOCK) JOIN sales.SalesInvoices i WITH(UPDLOCK,HOLDLOCK) ON i.TenantId=o.TenantId AND i.InvoiceId=o.OrderId WHERE o.TenantId=@tenant AND o.OrderId=@order AND o.OrderKind='MARKETPLACE' AND i.OrderType='MARKETPLACE' AND i.Status IN('HELD','SUSPENDED','COMPLETED','CANCELLED');",c,tx);P(q,"@tenant",tenant);P(q,"@order",order);
        return StringValue(await q.ExecuteScalarAsync(token))??throw new EntityNotFoundException("Marketplace parent order was not found for this tenant.");
    }

    private async Task<(string Status,Guid? Agent,string? Source,Guid? AgentUserId)> ReadMarketplaceGroupState(SqlConnection c,SqlTransaction tx,Guid tenant,Guid order,Guid group,CancellationToken token)
    {
        await using var q=new SqlCommand("SELECT g.FulfilmentStatus,g.DeliveryAgentId,g.AssignmentSource,a.UserId FROM commerce.MarketplaceFulfilmentGroups g WITH(UPDLOCK,HOLDLOCK) LEFT JOIN commerce.DeliveryAgents a ON a.TenantId=g.TenantId AND a.DeliveryAgentId=g.DeliveryAgentId WHERE g.TenantId=@tenant AND g.OrderId=@order AND g.FulfilmentGroupId=@group;",c,tx);P(q,"@tenant",tenant);P(q,"@order",order);P(q,"@group",group);await using var r=await q.ExecuteReaderAsync(token);if(!await r.ReadAsync(token))throw new EntityNotFoundException("Marketplace fulfilment group was not found for this tenant.");return(r.GetString(0),r.IsDBNull(1)?null:r.GetGuid(1),S(r,2),r.IsDBNull(3)?null:r.GetGuid(3));
    }

    private async Task<(Guid? Agent,string? Source)> ResolveMarketplaceAssignment(SqlConnection c,SqlTransaction tx,Guid tenant,Guid? explicitId,CancellationToken token)
    {
        if(explicitId is not null)await ValidateAgent(c,tx,tenant,explicitId.Value,true,token);
        await using var q=new SqlCommand("SELECT s.DeliveryEnabled,s.AutomaticAssignmentEnabled,s.DefaultDeliveryAgentId,ISNULL(a.IsActive,0),ISNULL(a.IsAvailable,0) FROM commerce.TenantDeliverySettings s LEFT JOIN commerce.DeliveryAgents a ON a.TenantId=s.TenantId AND a.DeliveryAgentId=s.DefaultDeliveryAgentId WHERE s.TenantId=@tenant;",c,tx);P(q,"@tenant",tenant);await using var r=await q.ExecuteReaderAsync(token);if(!await r.ReadAsync(token)||!r.GetBoolean(0))throw new BusinessRuleException("Delivery management is not enabled for this tenant.");var result=DeliveryAssignmentPolicy.Resolve(explicitId,r.GetBoolean(1),r.IsDBNull(2)?null:r.GetGuid(2),r.GetBoolean(3),r.GetBoolean(4));return(result.AgentId,result.Source);
    }

