    private static async Task ReconcileMarketplaceParent(SqlConnection c,SqlTransaction tx,Guid tenant,Guid order,CancellationToken token)
    {
        await using var q=new SqlCommand("DECLARE @current varchar(24)=(SELECT LifecycleStatus FROM commerce.MarketplaceOrders WITH(UPDLOCK,HOLDLOCK) WHERE TenantId=@tenant AND OrderId=@order);DECLARE @required int=(SELECT COUNT(*) FROM commerce.MarketplaceFulfilmentGroups WITH(UPDLOCK,HOLDLOCK) WHERE TenantId=@tenant AND OrderId=@order AND FulfilmentStatus<>'CANCELLED');DECLARE @delivered int=(SELECT COUNT(*) FROM commerce.MarketplaceFulfilmentGroups WITH(UPDLOCK,HOLDLOCK) WHERE TenantId=@tenant AND OrderId=@order AND FulfilmentStatus='DELIVERED');DECLARE @cancelled int=(SELECT COUNT(*) FROM commerce.MarketplaceFulfilmentGroups WHERE TenantId=@tenant AND OrderId=@order AND FulfilmentStatus='CANCELLED');DECLARE @target varchar(24)=CASE WHEN @required>0 AND @delivered=@required AND @cancelled=0 THEN 'FULFILLED' WHEN @delivered>0 THEN 'PARTIALLY_FULFILLED' ELSE @current END;IF @target<>@current UPDATE commerce.MarketplaceOrders SET LifecycleStatus=@target,UpdatedAt=SYSUTCDATETIME() WHERE TenantId=@tenant AND OrderId=@order AND LifecycleStatus=@current;",c,tx);P(q,"@tenant",tenant);P(q,"@order",order);await q.ExecuteNonQueryAsync(token);
    }

    private static async Task ValidateMarketplaceGroupRestock(SqlConnection c,SqlTransaction tx,Guid tenant,Guid group,Guid transaction,CancellationToken token)
    {
        await using(var header=new SqlCommand(@"SELECT COUNT(*) FROM commerce.MarketplaceFulfilmentGroups g
JOIN inventory.InventoryTransactions t ON t.TenantId=g.TenantId AND t.WarehouseId=g.WarehouseId AND t.TransactionId=@transaction AND t.TransactionType='ADJUSTMENT_IN' AND t.ReferenceType='STOCK_ADJUSTMENT'
JOIN inventory.StockAdjustments s ON s.TransactionId=t.TransactionId AND s.AdjustmentType='INCREASE' AND s.ApprovalStatus='APPROVED' AND s.ReasonCode IN('PHYSICAL_VERIFICATION','FOUND')
WHERE g.TenantId=@tenant AND g.FulfilmentGroupId=@group;",c,tx))
        {P(header,"@tenant",tenant);P(header,"@group",group);P(header,"@transaction",transaction);if(Convert.ToInt32(await header.ExecuteScalarAsync(token),CultureInfo.InvariantCulture)!=1)throw new BusinessRuleException("Restock evidence must be an approved stock increase for this group's warehouse.");}
        await using var compare=new SqlCommand(@";WITH expected AS(
 SELECT i.ProductId,a.ZoneId,a.BinId,a.BatchNo,a.SerialNo,SUM(a.AllocatedQuantity) Quantity
 FROM commerce.MarketplaceFulfilmentGroupItems gi JOIN commerce.MarketplaceOrderAllocations a ON a.TenantId=gi.TenantId AND a.AllocationId=gi.AllocationId
 JOIN sales.SalesInvoiceItems i ON i.InvoiceId=a.OrderId AND i.InvoiceItemId=a.InvoiceItemId
 WHERE gi.TenantId=@tenant AND gi.FulfilmentGroupId=@group GROUP BY i.ProductId,a.ZoneId,a.BinId,a.BatchNo,a.SerialNo),
 actual AS(
 SELECT si.ProductId,si.ZoneId,si.BinId,si.BatchNo,si.SerialNo,SUM(si.Quantity) Quantity
 FROM inventory.StockAdjustments s JOIN inventory.StockAdjustmentItems si ON si.StockAdjustmentId=s.StockAdjustmentId
 WHERE s.TransactionId=@transaction GROUP BY si.ProductId,si.ZoneId,si.BinId,si.BatchNo,si.SerialNo)
SELECT CASE WHEN EXISTS(SELECT 1 FROM expected e FULL OUTER JOIN actual a ON e.ProductId=a.ProductId AND ISNULL(e.ZoneId,'00000000-0000-0000-0000-000000000000')=ISNULL(a.ZoneId,'00000000-0000-0000-0000-000000000000') AND ISNULL(e.BinId,'00000000-0000-0000-0000-000000000000')=ISNULL(a.BinId,'00000000-0000-0000-0000-000000000000') AND ISNULL(e.BatchNo,N'')=ISNULL(a.BatchNo,N'') AND ISNULL(e.SerialNo,N'')=ISNULL(a.SerialNo,N'') WHERE e.Quantity IS NULL OR a.Quantity IS NULL OR e.Quantity<>a.Quantity) THEN 0 ELSE 1 END;",c,tx);
        P(compare,"@tenant",tenant);P(compare,"@group",group);P(compare,"@transaction",transaction);
        if(Convert.ToInt32(await compare.ExecuteScalarAsync(token),CultureInfo.InvariantCulture)!=1)throw new BusinessRuleException("The approved restock transaction must match every allocated product, lot and quantity exactly.");
        await using var used=new SqlCommand("SELECT COUNT(*) FROM commerce.MarketplaceFulfilmentRefundObligations WITH(UPDLOCK,HOLDLOCK) WHERE TenantId=@tenant AND RestockTransactionId=@transaction;",c,tx);P(used,"@tenant",tenant);P(used,"@transaction",transaction);
        if(Convert.ToInt32(await used.ExecuteScalarAsync(token),CultureInfo.InvariantCulture)>0)throw new BusinessRuleException("This stock restock transaction has already been linked to another cancellation.");
    }

    private sealed record MarketplaceRefundCalculation(string Status,decimal? Amount,string? Reason,bool PaymentCollected);
    private static async Task<MarketplaceRefundCalculation> CalculateMarketplaceGroupRefund(SqlConnection c,SqlTransaction tx,Guid tenant,Guid order,Guid group,CancellationToken token)
    {
        bool sharedAdjustment,partialItem,paymentCollected;decimal amount;
        await using(var q=new SqlCommand(@"SELECT CONVERT(bit,CASE WHEN i.DiscountAmount<>COALESCE((SELECT SUM(ii.DiscountAmount) FROM sales.SalesInvoiceItems ii WHERE ii.InvoiceId=i.InvoiceId),0) OR i.PromotionDiscountAmount<>0 OR i.DeliveryCharge<>0 OR i.DeliveryTaxAmount<>0 OR i.RoundOff<>0 THEN 1 ELSE 0 END),
CONVERT(bit,CASE WHEN EXISTS(SELECT 1 FROM (SELECT a.InvoiceItemId,SUM(a.AllocatedQuantity) Qty FROM commerce.MarketplaceFulfilmentGroupItems gi JOIN commerce.MarketplaceOrderAllocations a ON a.TenantId=gi.TenantId AND a.AllocationId=gi.AllocationId WHERE gi.TenantId=@tenant AND gi.FulfilmentGroupId=@group GROUP BY a.InvoiceItemId) ga JOIN sales.SalesInvoiceItems ii ON ii.InvoiceId=@order AND ii.InvoiceItemId=ga.InvoiceItemId WHERE ga.Qty<>ii.Quantity) THEN 1 ELSE 0 END),
CONVERT(bit,CASE WHEN i.PaidAmount>0 OR cc.CollectionStatus IN('COLLECTED','REFUND_DUE','REFUNDED') THEN 1 ELSE 0 END),
COALESCE((SELECT SUM(z.LineTotal) FROM (SELECT DISTINCT ii.InvoiceItemId,ii.LineTotal FROM commerce.MarketplaceFulfilmentGroupItems gi JOIN commerce.MarketplaceOrderAllocations a ON a.TenantId=gi.TenantId AND a.AllocationId=gi.AllocationId JOIN sales.SalesInvoiceItems ii ON ii.InvoiceId=a.OrderId AND ii.InvoiceItemId=a.InvoiceItemId WHERE gi.TenantId=@tenant AND gi.FulfilmentGroupId=@group) z),0)
FROM sales.SalesInvoices i LEFT JOIN commerce.MarketplaceCodCollections cc WITH(UPDLOCK,HOLDLOCK) ON cc.TenantId=i.TenantId AND cc.OrderId=i.InvoiceId WHERE i.TenantId=@tenant AND i.InvoiceId=@order AND i.OrderType='MARKETPLACE';",c,tx))
        {P(q,"@tenant",tenant);P(q,"@order",order);P(q,"@group",group);await using var r=await q.ExecuteReaderAsync(token);if(!await r.ReadAsync(token))throw new EntityNotFoundException("Marketplace invoice was not found for refund reconciliation.");sharedAdjustment=r.GetBoolean(0);partialItem=r.GetBoolean(1);paymentCollected=r.GetBoolean(2);amount=r.GetDecimal(3);}
        var reason=sharedAdjustment?"Invoice-level discount, delivery charge, delivery tax or round-off cannot be apportioned reliably.":partialItem?"The fulfilment group contains only part of an invoice item's quantity; per-unit invoice amount cannot be refunded safely.":null;
        if(reason is not null)return new("REVIEW_REQUIRED",null,reason,paymentCollected);
        if(amount<=0)return new("NO_REFUND_REQUIRED",0m,null,paymentCollected);
        return new("REFUND_REQUIRED",amount,null,paymentCollected);
    }

