    private static async Task<MarketplaceFulfilmentGroupDto> ReadMarketplaceGroup(SqlConnection c,Guid tenant,Guid order,Guid group,CancellationToken token)
    {
        Guid id,warehouse;int number;string warehouseName,seller,status,address;Guid? partner,supplier,agent;string? agentName,source,tracking,sellerName;DateTimeOffset? ready,dispatched,delivered,cancelled;
        await using(var q=new SqlCommand("SELECT g.FulfilmentGroupId,g.GroupNumber,g.WarehouseId,w.WarehouseName,g.SellerKind,g.PartnerSellerId,g.SupplierId,g.FulfilmentStatus,g.DeliveryAgentId,a.DisplayName,g.AssignmentSource,g.DeliveryAddressSnapshot,g.TrackingReference,g.ReadyAt,g.DispatchedAt,g.DeliveredAt,g.CancelledAt,CASE g.SellerKind WHEN 'OWNED' THEN N'GuturGo inventory' WHEN 'PARTNER' THEN COALESCE(ps.SellerName,N'Partner retailer') WHEN 'SUPPLIER' THEN COALESCE(s.SupplierName,N'Supplier') END FROM commerce.MarketplaceFulfilmentGroups g JOIN inventory.Warehouses w ON w.TenantId=g.TenantId AND w.WarehouseId=g.WarehouseId LEFT JOIN commerce.DeliveryAgents a ON a.TenantId=g.TenantId AND a.DeliveryAgentId=g.DeliveryAgentId LEFT JOIN commerce.PartnerSellers ps ON ps.OperatingTenantId=g.TenantId AND ps.PartnerSellerId=g.PartnerSellerId LEFT JOIN purchase.Suppliers s ON s.TenantId=g.TenantId AND s.SupplierId=g.SupplierId WHERE g.TenantId=@tenant AND g.OrderId=@order AND g.FulfilmentGroupId=@group;",c))
        {P(q,"@tenant",tenant);P(q,"@order",order);P(q,"@group",group);await using var r=await q.ExecuteReaderAsync(token);if(!await r.ReadAsync(token))throw new EntityNotFoundException("Marketplace fulfilment group was not found.");id=r.GetGuid(0);number=r.GetInt16(1);warehouse=r.GetGuid(2);warehouseName=r.GetString(3);seller=r.GetString(4);partner=r.IsDBNull(5)?null:r.GetGuid(5);supplier=r.IsDBNull(6)?null:r.GetGuid(6);status=r.GetString(7);agent=r.IsDBNull(8)?null:r.GetGuid(8);agentName=S(r,9);source=S(r,10);address=r.GetString(11);tracking=S(r,12);ready=r.IsDBNull(13)?null:r.GetDateTimeOffset(13);dispatched=r.IsDBNull(14)?null:r.GetDateTimeOffset(14);delivered=r.IsDBNull(15)?null:r.GetDateTimeOffset(15);cancelled=r.IsDBNull(16)?null:r.GetDateTimeOffset(16);sellerName=S(r,17);}
        var items=new List<MarketplaceFulfilmentItemDto>();await using(var q=new SqlCommand("SELECT i.InvoiceItemId,i.ProductId,p.ProductName,a.AllocatedQuantity FROM commerce.MarketplaceFulfilmentGroupItems gi JOIN commerce.MarketplaceOrderAllocations a ON a.TenantId=gi.TenantId AND a.AllocationId=gi.AllocationId JOIN sales.SalesInvoiceItems i ON i.InvoiceId=a.OrderId AND i.InvoiceItemId=a.InvoiceItemId JOIN master.Products p ON p.TenantId=gi.TenantId AND p.ProductId=i.ProductId WHERE gi.TenantId=@tenant AND gi.FulfilmentGroupId=@group ORDER BY p.ProductName,i.InvoiceItemId;",c))
        {P(q,"@tenant",tenant);P(q,"@group",group);await using var r=await q.ExecuteReaderAsync(token);while(await r.ReadAsync(token))items.Add(new(r.GetGuid(0),r.GetGuid(1),r.GetString(2),r.GetDecimal(3)));}
        var events=new List<MarketplaceFulfilmentGroupEventDto>();await using(var q=new SqlCommand("SELECT EventId,EventType,PreviousStatus,NewStatus,DeliveryAgentId,ActorUserId,Notes,CreatedAt FROM commerce.MarketplaceFulfilmentGroupEvents WHERE TenantId=@tenant AND FulfilmentGroupId=@group ORDER BY CreatedAt,EventId;",c))
        {P(q,"@tenant",tenant);P(q,"@group",group);await using var r=await q.ExecuteReaderAsync(token);while(await r.ReadAsync(token))events.Add(new(r.GetInt64(0),r.GetString(1),S(r,2),S(r,3),G(r,4),G(r,5),S(r,6),r.GetDateTimeOffset(7)));}
        string parentLifecycle,parentPayment,parentDelivery,parentRefund,parentCodStatus;Guid? codGroup;decimal? codExpected,codCollected;DateTimeOffset? codCollectedAt;string? groupRefundStatus,groupRefundReason;decimal? groupRefundAmount;
        await using(var q=new SqlCommand(@"SELECT o.LifecycleStatus,
COALESCE((SELECT TOP(1) p.Status FROM commerce.CommercePayments p WHERE p.TenantId=o.TenantId AND p.InvoiceId=o.OrderId ORDER BY CASE WHEN p.Status IN(N'PAID',N'CAPTURED') THEN 0 ELSE 1 END,p.AttemptNumber DESC,p.CreatedAt DESC),N'NOT_STARTED'),
COALESCE((SELECT CASE WHEN COUNT(*)=0 THEN N'NONE' WHEN SUM(CASE WHEN r.RefundStatus='REVIEW_REQUIRED' THEN 1 ELSE 0 END)>0 THEN N'REVIEW_REQUIRED' WHEN SUM(CASE WHEN r.RefundStatus IN('REFUND_REQUIRED','REFUND_PENDING') THEN 1 ELSE 0 END)>0 THEN N'REFUND_REQUIRED' WHEN SUM(CASE WHEN r.RefundStatus='REFUNDED' THEN 1 ELSE 0 END)>0 THEN N'REFUNDED' ELSE N'NO_REFUND_REQUIRED' END FROM commerce.MarketplaceFulfilmentRefundObligations r WHERE r.TenantId=o.TenantId AND r.OrderId=o.OrderId),N'NONE'),
COALESCE((SELECT TOP(1) cc.CollectionStatus FROM commerce.MarketplaceCodCollections cc WHERE cc.TenantId=o.TenantId AND cc.OrderId=o.OrderId),N'NONE'),
(SELECT TOP(1) cc.CollectionFulfilmentGroupId FROM commerce.MarketplaceCodCollections cc WHERE cc.TenantId=o.TenantId AND cc.OrderId=o.OrderId),
(SELECT TOP(1) cc.ExpectedAmount FROM commerce.MarketplaceCodCollections cc WHERE cc.TenantId=o.TenantId AND cc.OrderId=o.OrderId),
(SELECT TOP(1) cc.CollectedAmount FROM commerce.MarketplaceCodCollections cc WHERE cc.TenantId=o.TenantId AND cc.OrderId=o.OrderId),
(SELECT TOP(1) cc.CollectedAt FROM commerce.MarketplaceCodCollections cc WHERE cc.TenantId=o.TenantId AND cc.OrderId=o.OrderId),
(SELECT TOP(1) ro.RefundStatus FROM commerce.MarketplaceFulfilmentRefundObligations ro WHERE ro.TenantId=o.TenantId AND ro.OrderId=o.OrderId AND ro.FulfilmentGroupId=@group),
(SELECT TOP(1) ro.RefundAmount FROM commerce.MarketplaceFulfilmentRefundObligations ro WHERE ro.TenantId=o.TenantId AND ro.OrderId=o.OrderId AND ro.FulfilmentGroupId=@group),
(SELECT TOP(1) ro.ReviewReason FROM commerce.MarketplaceFulfilmentRefundObligations ro WHERE ro.TenantId=o.TenantId AND ro.OrderId=o.OrderId AND ro.FulfilmentGroupId=@group),
CASE
 WHEN COUNT(CASE WHEN g.FulfilmentStatus='CANCELLED' THEN 1 END)=COUNT(*) THEN N'CANCELLED'
 WHEN COUNT(CASE WHEN g.FulfilmentStatus='DELIVERED' THEN 1 END)>0 AND COUNT(CASE WHEN g.FulfilmentStatus='CANCELLED' THEN 1 END)>0 AND COUNT(CASE WHEN g.FulfilmentStatus IN('DELIVERED','CANCELLED') THEN 1 END)=COUNT(*) THEN N'PARTIALLY_CANCELLED'
