 WHEN COUNT(CASE WHEN g.FulfilmentStatus='DELIVERED' THEN 1 END)=COUNT(CASE WHEN g.FulfilmentStatus<>'CANCELLED' THEN 1 END) AND COUNT(CASE WHEN g.FulfilmentStatus<>'CANCELLED' THEN 1 END)>0 THEN N'DELIVERED'
 WHEN COUNT(CASE WHEN g.FulfilmentStatus='DELIVERED' THEN 1 END)>0 THEN N'PARTIALLY_DELIVERED'
 WHEN COUNT(CASE WHEN g.FulfilmentStatus='DELIVERY_FAILED' THEN 1 END)>0 THEN N'DELIVERY_ATTENTION'
 WHEN COUNT(CASE WHEN g.FulfilmentStatus='OUT_FOR_DELIVERY' THEN 1 END)>0 AND COUNT(CASE WHEN g.FulfilmentStatus='OUT_FOR_DELIVERY' THEN 1 END)<COUNT(*) THEN N'PARTIALLY_DISPATCHED'
 WHEN COUNT(CASE WHEN g.FulfilmentStatus='OUT_FOR_DELIVERY' THEN 1 END)>0 THEN N'OUT_FOR_DELIVERY'
 WHEN COUNT(CASE WHEN g.FulfilmentStatus='READY_FOR_DISPATCH' THEN 1 END)>0 THEN N'READY_FOR_PICKUP'
 WHEN COUNT(CASE WHEN g.FulfilmentStatus IN('PREPARING','PENDING') THEN 1 END)>0 THEN N'PREPARING'
 ELSE N'CONFIRMED' END
FROM commerce.MarketplaceOrders o JOIN commerce.MarketplaceFulfilmentGroups g ON g.TenantId=o.TenantId AND g.OrderId=o.OrderId
WHERE o.TenantId=@tenant AND o.OrderId=@order GROUP BY o.TenantId,o.OrderId,o.LifecycleStatus;",c))
        {P(q,"@tenant",tenant);P(q,"@order",order);P(q,"@group",group);await using var r=await q.ExecuteReaderAsync(token);if(!await r.ReadAsync(token))throw new EntityNotFoundException("Marketplace parent order was not found.");parentLifecycle=r.GetString(0);parentPayment=r.GetString(1);parentRefund=r.GetString(2);parentCodStatus=r.GetString(3);codGroup=G(r,4);codExpected=r.IsDBNull(5)?null:r.GetDecimal(5);codCollected=r.IsDBNull(6)?null:r.GetDecimal(6);codCollectedAt=r.IsDBNull(7)?null:r.GetDateTimeOffset(7);groupRefundStatus=S(r,8);groupRefundAmount=r.IsDBNull(9)?null:r.GetDecimal(9);groupRefundReason=S(r,10);parentDelivery=r.GetString(11);}
        return new(id,order,number,warehouse,warehouseName,seller,partner,supplier,status,agent,agentName,source,address,tracking,ready,dispatched,delivered,cancelled,items,events,parentLifecycle,parentPayment,parentDelivery,parentRefund,parentCodStatus,codGroup,codExpected,codCollected,codCollectedAt,sellerName,groupRefundStatus,groupRefundAmount,groupRefundReason);
