    public async Task<DeliveryDto> Assign(Guid tenantId,Guid deliveryId,AssignDeliveryInput input,Guid actorId,string actor,CancellationToken token)
    { await using var c=await Open(token);await using var tx=(SqlTransaction)await c.BeginTransactionAsync(token);Guid? old;string prior;await using(var read=new SqlCommand("SELECT d.DeliveryAgentId,d.DeliveryStatus FROM commerce.OrderDeliveries d WITH(UPDLOCK) JOIN sales.SalesInvoices i ON i.TenantId=d.TenantId AND i.InvoiceId=d.OrderId AND i.OrderType='STANDARD' WHERE d.TenantId=@tenant AND d.OrderDeliveryId=@id",c,tx)){P(read,"@tenant",tenantId);P(read,"@id",deliveryId);await using var r=await read.ExecuteReaderAsync(token);if(!await r.ReadAsync(token))throw new EntityNotFoundException("Delivery was not found.");old=r.IsDBNull(0)?null:r.GetGuid(0);prior=r.GetString(1);}if(prior is DeliveryStatuses.Delivered or DeliveryStatuses.Cancelled or DeliveryStatuses.Returned)throw new BusinessRuleException("A completed delivery cannot be reassigned.");Guid? next=input.DeliveryAgentId;if(next is not null)await ValidateAgent(c,tx,tenantId,next.Value,true,token);var status=next is null?DeliveryStatuses.Unassigned:(prior==DeliveryStatuses.Unassigned?DeliveryStatuses.Ready:prior);await using(var q=new SqlCommand("UPDATE commerce.OrderDeliveries SET DeliveryAgentId=@agent,AssignmentSource=CASE WHEN @agent IS NULL THEN NULL ELSE 'MANUAL' END,AssignedAt=CASE WHEN @agent IS NULL THEN NULL ELSE SYSUTCDATETIME() END,AssignedBy=CASE WHEN @agent IS NULL THEN NULL ELSE @actor END,DeliveryStatus=@status,UpdatedAt=SYSUTCDATETIME() WHERE TenantId=@tenant AND OrderDeliveryId=@id",c,tx)){P(q,"@agent",next);P(q,"@actor",actorId);P(q,"@status",status);P(q,"@tenant",tenantId);P(q,"@id",deliveryId);await q.ExecuteNonQueryAsync(token);}await Event(c,tx,tenantId,deliveryId,next is null?"UNASSIGNED":old is null?"ASSIGNED":"REASSIGNED",prior,status,old,next,actorId,input.Reason,token);await tx.CommitAsync(token);if(next is not null&&(await Settings(tenantId,token)).NotifyOnAssigned)await Notify(tenantId,deliveryId,DeliveryTemplateKeys.Assigned,null,token);return await Get(tenantId,deliveryId,null,true,token); }

    public Task<DeliveryDto> PickedUp(Guid t,Guid d,Guid u,string a,bool m,CancellationToken ct)=>Transition(t,d,u,a,m,DeliveryStatuses.PickedUp,[DeliveryStatuses.Ready,DeliveryStatuses.Assigned,DeliveryStatuses.Rescheduled],"PICKED_UP",null,ct);
    public async Task<DeliveryDto> OutForDelivery(Guid t,Guid d,Guid u,string a,bool m,CancellationToken ct){var result=await Transition(t,d,u,a,m,DeliveryStatuses.OutForDelivery,[DeliveryStatuses.PickedUp],"OUT_FOR_DELIVERY",null,ct);if((await Settings(t,ct)).NotifyOnOutForDelivery)await Notify(t,d,DeliveryTemplateKeys.OutForDelivery,null,ct);return result;}

    public async Task RequestOtp(Guid tenantId,Guid deliveryId,Guid userId,string actor,bool manage,CancellationToken token)
    { var settings=await Settings(tenantId,token);if(!settings.RequireDeliveryOtp)throw new BusinessRuleException("OTP proof of delivery is disabled for this tenant.");await using var c=await Open(token);await using var tx=(SqlTransaction)await c.BeginTransactionAsync(token);await AssertAccess(c,tx,tenantId,deliveryId,userId,manage,[DeliveryStatuses.OutForDelivery],token);var now=DateTimeOffset.UtcNow;int resend=0;await using(var old=new SqlCommand("SELECT ResendCount,LastSentAt FROM commerce.OrderDeliveryOtps WITH(UPDLOCK,HOLDLOCK) WHERE TenantId=@tenant AND OrderDeliveryId=@id",c,tx)){P(old,"@tenant",tenantId);P(old,"@id",deliveryId);await using var r=await old.ExecuteReaderAsync(token);if(await r.ReadAsync(token)){resend=r.GetInt32(0)+1;if(resend>settings.MaxOtpResends)throw new BusinessRuleException("Maximum OTP resend count has been reached.");if(now-r.GetDateTimeOffset(1)<TimeSpan.FromSeconds(settings.OtpResendCooldownSeconds))throw new BusinessRuleException("Please wait before requesting another OTP.");}}
        var otp=RandomNumberGenerator.GetInt32(1000,10000).ToString(CultureInfo.InvariantCulture);var salt=RandomNumberGenerator.GetBytes(32);var hash=OtpHash(tenantId,deliveryId,otp,salt);await using(var q=new SqlCommand(@"MERGE commerce.OrderDeliveryOtps AS target USING(SELECT @id OrderDeliveryId) source ON target.OrderDeliveryId=source.OrderDeliveryId WHEN MATCHED THEN UPDATE SET TenantId=@tenant,OtpHash=@hash,OtpSalt=@salt,ExpiresAt=@expires,AttemptCount=0,ResendCount=@resend,LastSentAt=@now,VerifiedAt=NULL,InvalidatedAt=NULL WHEN NOT MATCHED THEN INSERT(OrderDeliveryId,TenantId,OtpHash,OtpSalt,ExpiresAt,ResendCount,LastSentAt) VALUES(@id,@tenant,@hash,@salt,@expires,@resend,@now);",c,tx)){P(q,"@id",deliveryId);P(q,"@tenant",tenantId);P(q,"@hash",hash);P(q,"@salt",salt);P(q,"@expires",now.AddMinutes(settings.DeliveryOtpExpiryMinutes));P(q,"@resend",resend);P(q,"@now",now);await q.ExecuteNonQueryAsync(token);}await Event(c,tx,tenantId,deliveryId,"OTP_REQUESTED",DeliveryStatuses.OutForDelivery,DeliveryStatuses.OutForDelivery,null,null,userId,null,token);await tx.CommitAsync(token);await Notify(tenantId,deliveryId,DeliveryTemplateKeys.Otp,otp,token); }

    public async Task<DeliveryDto> ConfirmOtp(Guid tenantId,Guid deliveryId,Guid userId,ConfirmOtpInput input,string actor,bool manage,CancellationToken token)
    { if(input.Otp?.Length!=4||!input.Otp.All(char.IsDigit))throw new BusinessRuleException("A valid four-digit OTP is required.");var settings=await Settings(tenantId,token);await using var c=await Open(token);await using var tx=(SqlTransaction)await c.BeginTransactionAsync(token);var access=await AssertAccess(c,tx,tenantId,deliveryId,userId,manage,[DeliveryStatuses.OutForDelivery],token);if(settings.RequireCodConfirmation&&access.CodRequired&&!access.CodCollected&&access.Balance>0)throw new BusinessRuleException("COD collection must be confirmed before delivery.");byte[] hash,salt;DateTimeOffset expiry;int attempts;DateTimeOffset? verified,invalidated;await using(var q=new SqlCommand("SELECT OtpHash,OtpSalt,ExpiresAt,AttemptCount,VerifiedAt,InvalidatedAt FROM commerce.OrderDeliveryOtps WITH(UPDLOCK) WHERE TenantId=@tenant AND OrderDeliveryId=@id",c,tx)){P(q,"@tenant",tenantId);P(q,"@id",deliveryId);await using var r=await q.ExecuteReaderAsync(token);if(!await r.ReadAsync(token))throw new BusinessRuleException("Request a delivery OTP first.");hash=(byte[])r[0];salt=(byte[])r[1];expiry=r.GetDateTimeOffset(2);attempts=r.GetInt32(3);verified=r.IsDBNull(4)?null:r.GetDateTimeOffset(4);invalidated=r.IsDBNull(5)?null:r.GetDateTimeOffset(5);}if(verified is not null)return await CommitAndGet(tx,tenantId,deliveryId,token);if(invalidated is not null||expiry<=DateTimeOffset.UtcNow)throw new BusinessRuleException("The delivery OTP has expired. Request a new OTP.");if(attempts>=settings.MaxOtpAttempts)throw new BusinessRuleException("Maximum OTP attempts have been reached.");if(!CryptographicOperations.FixedTimeEquals(hash,OtpHash(tenantId,deliveryId,input.Otp,salt))){await using var bad=new SqlCommand("UPDATE commerce.OrderDeliveryOtps SET AttemptCount=AttemptCount+1,InvalidatedAt=CASE WHEN AttemptCount+1>=@max THEN SYSUTCDATETIME() END WHERE OrderDeliveryId=@id AND TenantId=@tenant",c,tx);P(bad,"@max",settings.MaxOtpAttempts);P(bad,"@id",deliveryId);P(bad,"@tenant",tenantId);await bad.ExecuteNonQueryAsync(token);await tx.CommitAsync(token);throw new BusinessRuleException("The delivery OTP is incorrect.");}await MarkDelivered(c,tx,tenantId,deliveryId,userId,"OTP",null,token);await using(var ok=new SqlCommand("UPDATE commerce.OrderDeliveryOtps SET VerifiedAt=SYSUTCDATETIME(),InvalidatedAt=SYSUTCDATETIME() WHERE OrderDeliveryId=@id AND TenantId=@tenant",c,tx)){P(ok,"@id",deliveryId);P(ok,"@tenant",tenantId);await ok.ExecuteNonQueryAsync(token);}await tx.CommitAsync(token);await Complete(tenantId,deliveryId,access.OrderId,access.CustomerId,actor,token);return await Get(tenantId,deliveryId,null,true,token); }

    public async Task<DeliveryDto> ConfirmWithoutOtp(Guid tenantId,Guid deliveryId,Guid userId,ConfirmDeliveryWithoutOtpInput input,string actor,bool manage,CancellationToken token)
    { if(string.IsNullOrWhiteSpace(input.Reason))throw new BusinessRuleException("A reason is required to confirm delivery without OTP.");var settings=await Settings(tenantId,token);if(settings.RequireDeliveryOtp)throw new BusinessRuleException("This tenant requires OTP proof of delivery.");await using var c=await Open(token);await using var tx=(SqlTransaction)await c.BeginTransactionAsync(token);var access=await AssertAccess(c,tx,tenantId,deliveryId,userId,manage,[DeliveryStatuses.OutForDelivery],token);if(settings.RequireCodConfirmation&&access.CodRequired&&!access.CodCollected&&access.Balance>0)throw new BusinessRuleException("COD collection must be confirmed before delivery.");await MarkDelivered(c,tx,tenantId,deliveryId,userId,"MANUAL",input.Reason.Trim(),token);await tx.CommitAsync(token);await Complete(tenantId,deliveryId,access.OrderId,access.CustomerId,actor,token);return await Get(tenantId,deliveryId,null,true,token); }

    public async Task<DeliveryDto> RecordCod(Guid tenantId,Guid deliveryId,Guid userId,CodCollectionInput input,string actor,bool manage,CancellationToken token)
    {
        tenantId=AuthenticatedTenant(tenantId);var method=input.PaymentMethod.Trim().ToUpperInvariant();if(method is not("CASH" or "UPI" or "ALREADY_PAID"))throw new BusinessRuleException("COD payment method must be Cash, UPI, or Already Paid.");
        await using var c=await Open(token);await using var tx=(SqlTransaction)await c.BeginTransactionAsync(token);await SetTenantContext(c,tx,tenantId,token);
        var row=await AssertAccess(c,tx,tenantId,deliveryId,userId,manage,[DeliveryStatuses.PickedUp,DeliveryStatuses.OutForDelivery,DeliveryStatuses.Ready],token);
        if(!row.CodRequired)throw new BusinessRuleException("This is not a COD delivery.");if(row.CodCollected)return await CommitAndGet(tx,tenantId,deliveryId,token);
        if(method=="ALREADY_PAID"&&row.Balance>0)throw new BusinessRuleException("The invoice still has an outstanding balance.");if(method!="ALREADY_PAID"&&input.Amount!=row.Balance)throw new BusinessRuleException("The collected amount must equal the current invoice balance.");
        if(method!="ALREADY_PAID"&&input.Amount>0)
        {
            var posted=await erpPayments.ApplyAsync(c,tx,new(tenantId,row.OrderId,method,input.Amount,input.Reference,actor),token);
            if(posted.InvoiceId!=row.OrderId||posted.BalanceAmount!=0)throw new BusinessRuleException("ERP COD collection did not settle the expected invoice balance.");
            await using var sync=new SqlCommand(@"DECLARE @payment uniqueidentifier=(SELECT TOP(1)PaymentId FROM commerce.CommercePayments WITH(UPDLOCK,HOLDLOCK) WHERE TenantId=@tenant AND InvoiceId=@invoice AND Provider=N'COD' AND Status=N'COD_PENDING' ORDER BY AttemptNumber DESC);
IF @payment IS NOT NULL BEGIN
 IF NOT EXISTS(SELECT 1 FROM commerce.PaymentApplications WHERE TenantId=@tenant AND PaymentId=@payment)
  INSERT commerce.PaymentApplications(PaymentApplicationId,TenantId,PaymentId,InvoiceId,Amount,Currency,AppliedBy)VALUES(NEWID(),@tenant,@payment,@invoice,@amount,N'INR',@actor);
 UPDATE commerce.CommercePayments SET Status=N'PAID',PaidAt=SYSUTCDATETIME(),VerifiedAt=SYSUTCDATETIME(),VerifiedBy=@user,AppliedAt=SYSUTCDATETIME(),ProviderReference=@reference,UpdatedAt=SYSUTCDATETIME() WHERE TenantId=@tenant AND PaymentId=@payment;
END",c,tx);P(sync,"@tenant",tenantId);P(sync,"@invoice",row.OrderId);P(sync,"@amount",input.Amount);P(sync,"@actor",actor);P(sync,"@user",userId);P(sync,"@reference",input.Reference);await sync.ExecuteNonQueryAsync(token);
        }
        else
        { await using var cancel=new SqlCommand("UPDATE commerce.CommercePayments SET Status=N'CANCELLED',UpdatedAt=SYSUTCDATETIME() WHERE TenantId=@tenant AND InvoiceId=@invoice AND Provider=N'COD' AND Status=N'COD_PENDING'",c,tx);P(cancel,"@tenant",tenantId);P(cancel,"@invoice",row.OrderId);await cancel.ExecuteNonQueryAsync(token); }
        await CompleteHeldInvoiceIfSettled(c,tx,row.OrderId,actor,token);
        await using(var q=new SqlCommand("UPDATE commerce.OrderDeliveries SET CodCollected=1,CodCollectedAt=SYSUTCDATETIME(),CodPaymentMethod=@method,CodReference=@reference,UpdatedAt=SYSUTCDATETIME() WHERE TenantId=@tenant AND OrderDeliveryId=@id AND CodCollected=0",c,tx)){P(q,"@method",method);P(q,"@reference",input.Reference);P(q,"@tenant",tenantId);P(q,"@id",deliveryId);await q.ExecuteNonQueryAsync(token);}
        await Event(c,tx,tenantId,deliveryId,"COD_COLLECTED",null,null,null,null,userId,$"Method: {method}; Amount: {input.Amount:0.00}",token);await tx.CommitAsync(token);return await Get(tenantId,deliveryId,null,true,token);
    }

    public async Task<DeliveryDto> Fail(Guid t,Guid d,Guid u,FailDeliveryInput x,string actor,bool manage,CancellationToken token){if(!DeliveryFailureReasons.All.Contains(x.Reason)||x.Reason.Equals("Other",StringComparison.OrdinalIgnoreCase)&&string.IsNullOrWhiteSpace(x.Details))throw new BusinessRuleException("Select a valid failure reason; details are required for Other.");var result=await Transition(t,d,u,actor,manage,DeliveryStatuses.Failed,[DeliveryStatuses.Ready,DeliveryStatuses.PickedUp,DeliveryStatuses.OutForDelivery],"FAILED",x.Reason+(string.IsNullOrWhiteSpace(x.Details)?null:$": {x.Details}"),token,"FailureReason=@reason,FailureDetails=@details,FailedAt=SYSUTCDATETIME(),",x.Reason,x.Details);if((await Settings(t,token)).NotifyOnDeliveryFailed)await Notify(t,d,DeliveryTemplateKeys.Failed,null,token);return result;}
    public async Task<DeliveryDto> Reschedule(Guid t,Guid d,Guid u,RescheduleDeliveryInput x,string actor,bool manage,CancellationToken token){if(x.NewDate<DateTimeOffset.UtcNow.Date)throw new BusinessRuleException("The rescheduled date cannot be in the past.");var result=await Transition(t,d,u,actor,manage,DeliveryStatuses.Rescheduled,[DeliveryStatuses.Failed,DeliveryStatuses.Ready,DeliveryStatuses.PickedUp,DeliveryStatuses.OutForDelivery],"RESCHEDULED",x.Reason,token,"ScheduledDate=@date,TimeWindow=@window,RescheduledAt=SYSUTCDATETIME(),",x.NewDate.Date,x.TimeWindow);if(x.DeliveryAgentId is not null)result=await Assign(t,d,new(x.DeliveryAgentId,"Reassigned during reschedule"),u,actor,token);await Notify(t,d,DeliveryTemplateKeys.Rescheduled,null,token);return result;}
    public async Task<DeliveryDto> OverrideDelivered(Guid t,Guid d,OverrideDeliveryInput x,Guid u,string actor,CancellationToken token){if(string.IsNullOrWhiteSpace(x.Reason))throw new BusinessRuleException("A reason is required for delivery without OTP.");await using var c=await Open(token);await using var tx=(SqlTransaction)await c.BeginTransactionAsync(token);var row=await AssertAccess(c,tx,t,d,u,true,[DeliveryStatuses.Ready,DeliveryStatuses.PickedUp,DeliveryStatuses.OutForDelivery],token);var settings=await Settings(t,token);if(settings.RequireCodConfirmation&&row.CodRequired&&!row.CodCollected&&row.Balance>0&&!x.CodException)throw new BusinessRuleException("COD is still outstanding; an authorized COD exception must be explicit.");await MarkDelivered(c,tx,t,d,u,"MANUAL_OVERRIDE",x.Reason,token);await tx.CommitAsync(token);await Complete(t,d,row.OrderId,row.CustomerId,actor,token);return await Get(t,d,null,true,token);}

    private async Task<DeliveryDto> Transition(Guid t,Guid d,Guid u,string actor,bool manage,string next,IReadOnlyCollection<string> allowed,string eventType,string? notes,CancellationToken token,string extra="",object? extra1=null,object? extra2=null){await using var c=await Open(token);await using var tx=(SqlTransaction)await c.BeginTransactionAsync(token);var row=await AssertAccess(c,tx,t,d,u,manage,allowed,token);await EnsurePrepaidSettled(c,tx,t,row.OrderId,token);await using var q=new SqlCommand($"UPDATE commerce.OrderDeliveries SET {extra} DeliveryStatus=@next,{Timestamp(next)}UpdatedAt=SYSUTCDATETIME() WHERE TenantId=@tenant AND OrderDeliveryId=@id AND DeliveryStatus=@prior",c,tx);P(q,"@next",next);P(q,"@tenant",t);P(q,"@id",d);P(q,"@prior",row.Status);if(extra1 is not null)P(q,next==DeliveryStatuses.Rescheduled?"@date":"@reason",extra1);if(extra2 is not null)P(q,next==DeliveryStatuses.Rescheduled?"@window":"@details",extra2);if(await q.ExecuteNonQueryAsync(token)!=1)throw new BusinessRuleException("The delivery state changed; refresh and retry.");await SyncIntegrationDeliveryStatus(c,tx,t,row.OrderId,next,token);await Event(c,tx,t,d,eventType,row.Status,next,null,null,u,notes,token);await tx.CommitAsync(token);return await Get(t,d,null,true,token);}
    private static string Timestamp(string status)=>status switch{DeliveryStatuses.PickedUp=>"PickedUpAt=SYSUTCDATETIME(),",DeliveryStatuses.OutForDelivery=>"OutForDeliveryAt=SYSUTCDATETIME(),",_=>""};
    private static async Task EnsurePrepaidSettled(SqlConnection c,SqlTransaction tx,Guid tenant,Guid order,CancellationToken token)
    {
        await using var q=new SqlCommand("SELECT TOP(1) CASE WHEN w.SourceChannel=N'STOREFRONT' AND COALESCE(w.PaymentType,N'')<>N'COD' AND NOT EXISTS(SELECT 1 FROM commerce.CommercePayments cp WHERE cp.TenantId=i.TenantId AND cp.InvoiceId=i.InvoiceId AND cp.Status IN(N'PAID',N'CAPTURED')) THEN 1 ELSE 0 END FROM sales.SalesInvoices i LEFT JOIN integration.WhatsAppCommerceOrders w ON w.TenantId=i.TenantId AND w.InvoiceId=i.InvoiceId WHERE i.TenantId=@tenant AND i.InvoiceId=@order",c,tx);
        P(q,"@tenant",tenant);P(q,"@order",order);
        if(Convert.ToInt32(await q.ExecuteScalarAsync(token),CultureInfo.InvariantCulture)==1)throw new BusinessRuleException("Payment must be verified before this prepaid storefront order can enter delivery.");
    }
    private async Task<(Guid? Agent,string? Source)> ResolveAssignment(SqlConnection c,SqlTransaction tx,Guid tenant,Guid? explicitId,CancellationToken token){if(explicitId is not null)await ValidateAgent(c,tx,tenant,explicitId.Value,true,token);await using var q=new SqlCommand("SELECT s.DeliveryEnabled,s.AutomaticAssignmentEnabled,s.DefaultDeliveryAgentId,ISNULL(a.IsActive,0),ISNULL(a.IsAvailable,0) FROM commerce.TenantDeliverySettings s LEFT JOIN commerce.DeliveryAgents a ON a.DeliveryAgentId=s.DefaultDeliveryAgentId AND a.TenantId=s.TenantId WHERE s.TenantId=@tenant",c,tx);P(q,"@tenant",tenant);await using var r=await q.ExecuteReaderAsync(token);if(!await r.ReadAsync(token))throw new BusinessRuleException("Delivery settings are not configured for this tenant.");if(!r.GetBoolean(0))throw new BusinessRuleException("Delivery Management is disabled for this tenant.");var decision=DeliveryAssignmentPolicy.Resolve(explicitId,r.GetBoolean(1),r.IsDBNull(2)?null:r.GetGuid(2),r.GetBoolean(3),r.GetBoolean(4));return(decision.AgentId,decision.Source);}
    private static async Task ValidateAgent(SqlConnection c,SqlTransaction tx,Guid tenant,Guid id,bool available,CancellationToken token){await using var q=new SqlCommand("SELECT COUNT(1) FROM commerce.DeliveryAgents a JOIN core.Users u ON u.Id=a.UserId AND u.TenantId=a.TenantId AND u.IsActive=1 AND u.IsDeleted=0 WHERE a.TenantId=@tenant AND a.DeliveryAgentId=@id AND a.IsActive=1 AND (@available=0 OR a.IsAvailable=1)",c,tx);P(q,"@tenant",tenant);P(q,"@id",id);P(q,"@available",available);if(Convert.ToInt32(await q.ExecuteScalarAsync(token),CultureInfo.InvariantCulture)!=1)throw new BusinessRuleException("The selected delivery agent is inactive, unavailable, or belongs to another tenant.");}
    private sealed record AccessRow(string Status,Guid OrderId,Guid? CustomerId,bool CodRequired,bool CodCollected,decimal Balance);
    private static async Task<AccessRow> AssertAccess(SqlConnection c,SqlTransaction tx,Guid tenant,Guid delivery,Guid user,bool manage,IReadOnlyCollection<string> statuses,CancellationToken token){var names=statuses.Select((_,i)=>$"@s{i}").ToArray();await using var q=new SqlCommand($"SELECT d.DeliveryStatus,d.OrderId,i.CustomerId,d.CodRequired,d.CodCollected,i.BalanceAmount FROM commerce.OrderDeliveries d JOIN sales.SalesInvoices i ON i.InvoiceId=d.OrderId AND i.TenantId=d.TenantId AND i.OrderType='STANDARD' LEFT JOIN commerce.DeliveryAgents a ON a.DeliveryAgentId=d.DeliveryAgentId AND a.TenantId=d.TenantId WHERE d.TenantId=@tenant AND d.OrderDeliveryId=@id AND (@manage=1 OR a.UserId=@user) AND d.DeliveryStatus IN({string.Join(',',names)})",c,tx);P(q,"@tenant",tenant);P(q,"@id",delivery);P(q,"@manage",manage);P(q,"@user",user);for(var i=0;i<statuses.Count;i++)P(q,names[i],statuses.ElementAt(i));await using var r=await q.ExecuteReaderAsync(token);if(!await r.ReadAsync(token))throw new EntityNotFoundException("The delivery is not assigned to the current user or is not in an allowed state.");return new(r.GetString(0),r.GetGuid(1),r.IsDBNull(2)?null:r.GetGuid(2),r.GetBoolean(3),r.GetBoolean(4),r.GetDecimal(5));}
    private static async Task MarkDelivered(SqlConnection c,SqlTransaction tx,Guid tenant,Guid delivery,Guid actor,string proof,string? notes,CancellationToken token){Guid orderId;await using(var order=new SqlCommand("SELECT OrderId FROM commerce.OrderDeliveries WHERE TenantId=@tenant AND OrderDeliveryId=@id",c,tx)){P(order,"@tenant",tenant);P(order,"@id",delivery);if(await order.ExecuteScalarAsync(token) is not Guid found)throw new EntityNotFoundException("The delivery was not found.");orderId=found;await EnsurePrepaidSettled(c,tx,tenant,orderId,token);}await using var q=new SqlCommand("UPDATE commerce.OrderDeliveries SET DeliveryStatus='DELIVERED',ProofType=@proof,OtpVerified=CASE WHEN @proof='OTP' THEN 1 ELSE OtpVerified END,OtpVerifiedAt=CASE WHEN @proof='OTP' THEN SYSUTCDATETIME() ELSE OtpVerifiedAt END,DeliveredAt=SYSUTCDATETIME(),UpdatedAt=SYSUTCDATETIME() WHERE TenantId=@tenant AND OrderDeliveryId=@id AND DeliveryStatus<>'DELIVERED'",c,tx);P(q,"@proof",proof);P(q,"@tenant",tenant);P(q,"@id",delivery);if(await q.ExecuteNonQueryAsync(token)==0)throw new BusinessRuleException("Delivery is already completed.");await SyncIntegrationDeliveryStatus(c,tx,tenant,orderId,DeliveryStatuses.Delivered,token);await Event(c,tx,tenant,delivery,proof=="OTP"?"OTP_VERIFIED_AND_DELIVERED":"DELIVERED_OVERRIDE",DeliveryStatuses.OutForDelivery,DeliveryStatuses.Delivered,null,null,actor,notes,token);}
    private static async Task CompleteHeldInvoiceIfSettled(SqlConnection c,SqlTransaction tx,Guid order,string actor,CancellationToken token)
    {
        await using var status=new SqlCommand("SELECT Status,BalanceAmount FROM sales.SalesInvoices WITH(UPDLOCK,HOLDLOCK) WHERE InvoiceId=@invoice",c,tx);P(status,"@invoice",order);await using var r=await status.ExecuteReaderAsync(token);if(!await r.ReadAsync(token))throw new EntityNotFoundException("The invoice was not found.");var invoiceStatus=r.GetString(0);var balance=r.GetDecimal(1);await r.DisposeAsync();
        if(balance!=0||invoiceStatus is not("HELD" or "SUSPENDED"))return;
        await using var complete=new SqlCommand("sales.POS_TransitionHeldInvoice",c,tx){CommandType=CommandType.StoredProcedure};P(complete,"@InvoiceId",order);P(complete,"@Action","COMPLETE");P(complete,"@ModifiedBy",actor);await complete.ExecuteNonQueryAsync(token);
    }
    private static async Task SyncIntegrationDeliveryStatus(SqlConnection c,SqlTransaction tx,Guid tenant,Guid order,string status,CancellationToken token)
    {
        var integrationStatus=status switch{DeliveryStatuses.PickedUp or DeliveryStatuses.OutForDelivery=>"ON_THE_WAY",DeliveryStatuses.Delivered=>"DELIVERED",_=>null};if(integrationStatus is null)return;
        await using var q=new SqlCommand("UPDATE integration.WhatsAppCommerceOrders SET DeliveryStatus=@status,DispatchedOn=CASE WHEN @status IN(N'ON_THE_WAY',N'DELIVERED') AND DispatchedOn IS NULL THEN SYSUTCDATETIME() ELSE DispatchedOn END,DeliveredOn=CASE WHEN @status=N'DELIVERED' THEN COALESCE(DeliveredOn,SYSUTCDATETIME()) ELSE DeliveredOn END WHERE TenantId=@tenant AND InvoiceId=@invoice AND SourceChannel=N'STOREFRONT'",c,tx);P(q,"@status",integrationStatus);P(q,"@tenant",tenant);P(q,"@invoice",order);await q.ExecuteNonQueryAsync(token);
    }
    private async Task Complete(Guid tenant,Guid delivery,Guid order,Guid? customer,string actor,CancellationToken token){await publisher.Publish(new OrderDeliveryCompletedEvent(tenant,order,delivery,customer,actor),token);if((await Settings(tenant,token)).NotifyOnDelivered)await Notify(tenant,delivery,DeliveryTemplateKeys.Delivered,null,token);}
    private byte[] OtpHash(Guid tenant,Guid delivery,string otp,byte[] salt){var secret=configuration["Delivery:OtpPepper"]??configuration["Jwt:SigningKey"]??throw new InvalidOperationException("Delivery OTP pepper is not configured.");using var h=new HMACSHA256(Encoding.UTF8.GetBytes(secret));return h.ComputeHash(Encoding.UTF8.GetBytes($"{tenant:N}:{delivery:N}:{Convert.ToHexString(salt)}:{otp}"));}
    private byte[] MarketplaceOtpHash(Guid tenant,Guid order,Guid group,string otp,byte[] salt){var secret=configuration["Delivery:OtpPepper"]??configuration["Jwt:SigningKey"]??throw new InvalidOperationException("Delivery OTP pepper is not configured.");using var h=new HMACSHA256(Encoding.UTF8.GetBytes(secret));return h.ComputeHash(Encoding.UTF8.GetBytes($"{tenant:N}:{order:N}:{group:N}:{Convert.ToHexString(salt)}:{otp}"));}
    private byte[] MarketplaceOtpFingerprint(Guid tenant,Guid order,string otp){var secret=configuration["Delivery:OtpPepper"]??configuration["Jwt:SigningKey"]??throw new InvalidOperationException("Delivery OTP pepper is not configured.");using var h=new HMACSHA256(Encoding.UTF8.GetBytes(secret));return h.ComputeHash(Encoding.UTF8.GetBytes($"MARKETPLACE-OTP:{tenant:N}:{order:N}:{otp}"));}

    private async Task NotifyMarketplaceGroupOtp(Guid tenant,Guid orderId,Guid groupId,string otp,int expiryMinutes,CancellationToken token)
    {
        string? mobile,template,mode,api,phone,protectedToken;string orderNumber,store;short groupNumber;
        await using var c=await Open(token);
        await using(var q=new SqlCommand(@"SELECT cu.Mobile,i.InvoiceNumber,t.Name,g.GroupNumber,s.OtpTemplateName,w.ProviderMode,w.ApiVersion,w.PhoneNumberId,w.AccessTokenProtected
FROM commerce.MarketplaceFulfilmentGroups g JOIN sales.SalesInvoices i ON i.TenantId=g.TenantId AND i.InvoiceId=g.OrderId AND i.OrderType='MARKETPLACE'
JOIN sales.Customers cu ON cu.TenantId=i.TenantId AND cu.CustomerId=i.CustomerId JOIN core.Tenants t ON t.TenantId=g.TenantId
JOIN commerce.TenantDeliverySettings s ON s.TenantId=g.TenantId LEFT JOIN integration.WhatsAppConfigurations w ON w.TenantId=g.TenantId AND w.IsEnabled=1
WHERE g.TenantId=@tenant AND g.OrderId=@order AND g.FulfilmentGroupId=@group;",c))
        {P(q,"@tenant",tenant);P(q,"@order",orderId);P(q,"@group",groupId);await using var r=await q.ExecuteReaderAsync(token);if(!await r.ReadAsync(token))return;mobile=S(r,0);orderNumber=r.GetString(1);store=r.GetString(2);groupNumber=r.GetInt16(3);template=S(r,4);mode=S(r,5);api=S(r,6);phone=S(r,7);protectedToken=S(r,8);}
        if(string.IsNullOrWhiteSpace(mobile)||string.IsNullOrWhiteSpace(mode)||!ShouldCreateNotification(mode,outboundSafety))
        {await UpdateMarketplaceOtpNotification(tenant,orderId,groupId,"SUPPRESSED",null,"Delivery OTP notification is suppressed by missing configuration or Development outbound safety.",token);return;}
        var message=$"Delivery OTP for order #{orderNumber}, delivery {groupNumber}: {otp}. It expires in {expiryMinutes} minutes. Do not share it except with your delivery agent.";
        WhatsAppTransactionalMessageResult result;
        try
        {
            var provider=providers.Resolve(mode);var accessToken=mode.Equals("MOCK",StringComparison.OrdinalIgnoreCase)?string.Empty:protection.CreateProtector("WhatsBiz.WhatsApp.Secrets.v1").Unprotect(protectedToken??throw new BusinessRuleException("Stored WhatsApp credential cannot be decrypted."));
            result=await provider.SendTransactionalAsync(new(api??"v22.0",phone??string.Empty,accessToken,mobile,"DELIVERY_OTP",template,"en",message,[ $"{orderNumber} - Delivery {groupNumber}",otp ]),token);
        }
