    private async Task Notify(Guid tenant,Guid delivery,string key,string? otp,CancellationToken token)
    { Guid notification=Guid.NewGuid();string? mobile,order,customer,agent,store,template,mode,api,phone,protectedToken;await using(var c=await Open(token)){await using var q=new SqlCommand(@"SELECT d.CustomerMobileSnapshot,i.InvoiceNumber,d.CustomerNameSnapshot,a.DisplayName,t.Name,CASE @key WHEN 'DELIVERY_ASSIGNED' THEN s.AssignedTemplateName WHEN 'OUT_FOR_DELIVERY' THEN s.OutForDeliveryTemplateName WHEN 'DELIVERY_OTP' THEN s.OtpTemplateName WHEN 'ORDER_DELIVERED' THEN s.DeliveredTemplateName WHEN 'DELIVERY_FAILED' THEN s.FailedTemplateName ELSE s.RescheduledTemplateName END,w.ProviderMode,w.ApiVersion,w.PhoneNumberId,w.AccessTokenProtected FROM commerce.OrderDeliveries d JOIN sales.SalesInvoices i ON i.InvoiceId=d.OrderId JOIN core.Tenants t ON t.TenantId=d.TenantId LEFT JOIN commerce.DeliveryAgents a ON a.DeliveryAgentId=d.DeliveryAgentId JOIN commerce.TenantDeliverySettings s ON s.TenantId=d.TenantId LEFT JOIN integration.WhatsAppConfigurations w ON w.TenantId=d.TenantId AND w.IsEnabled=1 WHERE d.TenantId=@tenant AND d.OrderDeliveryId=@id",c);P(q,"@key",key);P(q,"@tenant",tenant);P(q,"@id",delivery);await using var r=await q.ExecuteReaderAsync(token);if(!await r.ReadAsync(token))return;mobile=S(r,0);order=r.GetString(1);customer=r.GetString(2);agent=S(r,3);store=r.GetString(4);template=S(r,5);mode=S(r,6);api=S(r,7);phone=S(r,8);protectedToken=S(r,9);if(string.IsNullOrWhiteSpace(mobile)||string.IsNullOrWhiteSpace(mode)||!ShouldCreateNotification(mode,outboundSafety))return;await r.DisposeAsync();await using var insert=new SqlCommand("INSERT commerce.OrderDeliveryNotifications(NotificationId,TenantId,OrderDeliveryId,TemplateKey,RecipientMasked,Status,ProviderMode) VALUES(@n,@tenant,@id,@key,@recipient,'PENDING',@mode)",c);P(insert,"@n",notification);P(insert,"@tenant",tenant);P(insert,"@id",delivery);P(insert,"@key",key);P(insert,"@recipient",Mask(mobile));P(insert,"@mode",mode);await insert.ExecuteNonQueryAsync(token);}
        var message=key switch{DeliveryTemplateKeys.Assigned=>$"Your order #{order} has been assigned to {agent} from {store}.",DeliveryTemplateKeys.OutForDelivery=>$"Your order is out for delivery.\nOrder: #{order}\nDelivery Agent: {agent}\nYour order from {store} will reach you soon.",DeliveryTemplateKeys.Otp=>$"Delivery OTP for order #{order}: {otp}. It expires shortly. Do not share it except with your delivery agent.",DeliveryTemplateKeys.Delivered=>$"✅ Order Delivered\nYour order #{order} has been successfully delivered.\nThank you for shopping with {store}.",DeliveryTemplateKeys.Failed=>$"Delivery attempt for order #{order} was unsuccessful. {store} will contact you.",_=>$"Delivery for order #{order} has been rescheduled by {store}."};
        WhatsAppTransactionalMessageResult result;try{var provider=providers.Resolve(mode!);var tokenValue=mode!.Equals("MOCK",StringComparison.OrdinalIgnoreCase)?string.Empty:protection.CreateProtector("WhatsBiz.WhatsApp.Secrets.v1").Unprotect(protectedToken??throw new BusinessRuleException("Stored WhatsApp credential cannot be decrypted."));result=await provider.SendTransactionalAsync(new(api??"v22.0",phone??string.Empty,tokenValue,mobile!,key,template,"en",message,key==DeliveryTemplateKeys.Otp?[order,otp??string.Empty]:[order,agent??string.Empty,store]),token);}catch(Exception ex) when(ex is not OperationCanceledException){result=new(false,null,DateTimeOffset.UtcNow,"WhatsApp delivery notification could not be sent.");}
        await using var c2=await Open(token);await using var update=new SqlCommand("UPDATE commerce.OrderDeliveryNotifications SET Status=@status,ProviderMessageId=@provider,AttemptCount=AttemptCount+1,Retryable=@retry,LastError=@error,LastAttemptAt=SYSUTCDATETIME(),SentAt=CASE WHEN @status='SENT' THEN SYSUTCDATETIME() END WHERE NotificationId=@id AND TenantId=@tenant",c2);P(update,"@status",result.Succeeded?"SENT":"FAILED");P(update,"@provider",result.ProviderMessageId);P(update,"@retry",!result.Succeeded);P(update,"@error",result.Succeeded?null:result.SafeMessage);P(update,"@id",notification);P(update,"@tenant",tenant);await update.ExecuteNonQueryAsync(token);if(result.Succeeded&&result.ProviderMessageId is not null&&usageBilling is not null)await usageBilling.RecordAcceptedAsync(new(tenant,mode!,phone??string.Empty,result.ProviderMessageId,mobile!,template,WhatsAppMessageCategories.Unknown,result.AttemptedAt),token);
    }
