    private static async Task<IReadOnlyCollection<DeliveryDto>> QueryDeliveries(SqlConnection c,Guid tenant,Guid? user,bool manage,DeliveryQuery f,CancellationToken token){var rows=new List<DeliveryDto>();await using var q=new SqlCommand(@"SELECT d.OrderDeliveryId,d.OrderId,i.InvoiceNumber,i.InvoiceDate,d.DeliveryStatus,d.DeliveryAgentId,a.DisplayName,d.AssignmentSource,d.CustomerNameSnapshot,d.CustomerMobileSnapshot,d.DeliveryAddressSnapshot,d.DeliveryNotes,i.GrandTotal,d.CodRequired,d.CodAmount,d.CodCollected,d.CodPaymentMethod,d.ScheduledDate,d.TimeWindow,d.SourceChannel,d.OtpVerified,d.UpdatedAt,d.Latitude,d.Longitude,d.CodCollectedAt,d.CodReference,d.ProofType,d.DeliveredAt,cod.Amount,cod.AppliedBy,cod.AppliedAt FROM commerce.OrderDeliveries d JOIN sales.SalesInvoices i ON i.InvoiceId=d.OrderId AND i.TenantId=d.TenantId AND i.OrderType='STANDARD' LEFT JOIN commerce.DeliveryAgents a ON a.DeliveryAgentId=d.DeliveryAgentId AND a.TenantId=d.TenantId OUTER APPLY(SELECT TOP(1) pa.Amount,pa.AppliedBy,pa.AppliedAt FROM commerce.PaymentApplications pa JOIN commerce.CommercePayments cp ON cp.TenantId=pa.TenantId AND cp.PaymentId=pa.PaymentId WHERE pa.TenantId=d.TenantId AND pa.InvoiceId=d.OrderId AND cp.Provider=N'COD' AND cp.Status IN(N'PAID',N'CAPTURED') ORDER BY pa.AppliedAt DESC) cod WHERE d.TenantId=@tenant AND (@manage=1 OR a.UserId=@user) AND (@status IS NULL OR d.DeliveryStatus=@status) AND (@agent IS NULL OR d.DeliveryAgentId=@agent) AND (@payment IS NULL OR (@payment='COD' AND d.CodRequired=1) OR (@payment='PREPAID' AND d.CodRequired=0)) AND (@from IS NULL OR i.InvoiceDate>=@from) AND (@to IS NULL OR i.InvoiceDate<@to) AND (@search IS NULL OR i.InvoiceNumber LIKE '%'+@search+'%' OR d.CustomerNameSnapshot LIKE '%'+@search+'%' OR CONVERT(nvarchar(36),d.OrderDeliveryId)=@search) ORDER BY d.UpdatedAt DESC",c);P(q,"@tenant",tenant);P(q,"@manage",manage);P(q,"@user",user);P(q,"@status",f.Status);P(q,"@agent",f.AgentId);P(q,"@payment",f.PaymentType);P(q,"@from",f.From);P(q,"@to",f.To);P(q,"@search",f.Search);await using var r=await q.ExecuteReaderAsync(token);while(await r.ReadAsync(token)){var address=r.GetString(10);var nav=!r.IsDBNull(22)&&!r.IsDBNull(23)?$"https://www.google.com/maps/search/?api=1&query={r.GetDecimal(22).ToString(CultureInfo.InvariantCulture)},{r.GetDecimal(23).ToString(CultureInfo.InvariantCulture)}":$"https://www.google.com/maps/search/?api=1&query={Uri.EscapeDataString(address)}";rows.Add(new(r.GetGuid(0),r.GetGuid(1),r.GetString(2),r.GetDateTimeOffset(3),r.GetString(4),G(r,5),S(r,6),S(r,7),r.GetString(8),S(r,9),address,S(r,11),r.GetDecimal(12),r.GetBoolean(13),r.GetDecimal(14),r.GetBoolean(15),S(r,16),r.IsDBNull(17)?null:new DateTimeOffset(r.GetDateTime(17),TimeSpan.Zero),S(r,18),r.GetString(19),r.GetBoolean(20),r.GetDateTimeOffset(21),nav,r.IsDBNull(28)?null:r.GetDecimal(28),r.IsDBNull(30)?null:r.GetDateTimeOffset(30),S(r,25),S(r,29),r.IsDBNull(27)?null:r.GetDateTimeOffset(27),S(r,26)));}return rows;}
